INSERT INTO soal_baru VALUES
  (1, 'Seorang pustakawan di perpustakaan umum kabupaten (rekaan) mencatat bahwa pojok baca digital ramai pada bulan pertama, lalu sepi. Ia menulis pertanyaan penelitian: "Mengapa pengunjung remaja jarang kembali ke pojok baca digital setelah kunjungan pertama?" Paradigma apa yang paling sesuai untuk pertanyaan itu, dan apa alasannya?', '["Kuantitatif, karena kata \"jarang\" menunjukkan frekuensi kunjungan yang dapat dihitung dari catatan buku tamu", "R&D, karena pada akhirnya pojok baca digital itu tetap perlu diperbaiki agar kembali ramai dikunjungi remaja", "Kualitatif, karena pertanyaan itu menuntut pemahaman motif dan pengalaman remaja, bukan jumlah kunjungan", "Kuantitatif, karena jumlah remaja di kabupaten itu besar sehingga perlu sampel dan uji statistik yang memadai"]'::JSONB, 2, '[C4] Kata tanya "mengapa" menuntut alasan dan pengalaman, ciri pertanyaan kualitatif. Kata "jarang" memang menyiratkan frekuensi, tetapi frekuensinya sudah diketahui dari catatan; yang belum diketahui adalah sebabnya.', 1),
  (1, 'Seorang mahasiswa mengamati perpustakaan SMA (rekaan) selama 30 menit, lalu menulis di kolom Masalah pada tabel AM-1: "Perpustakaan SMA ini belum memiliki aplikasi katalog daring, sehingga layanannya tertinggal." Apa kelemahan utama rumusan masalah itu?', '["Rumusan itu sudah berupa gagasan solusi, sehingga produk diputuskan sebelum kondisi teramati ditulis", "Rumusan itu terlalu pendek, karena kolom masalah pada AM-1 meminta dua sampai tiga kalimat yang utuh", "Rumusan itu masih berupa gejala, karena belum menyebut panjang antrean yang tampak di meja layanan", "Rumusan itu memakai sudut pandang petugas, padahal masalah harus ditulis dari sisi para siswa pengguna"]'::JSONB, 0, '[C4] Kalimat "belum memiliki aplikasi" menyebut solusi, bukan kondisi yang bisa diamati, sehingga dosen tidak dapat menilai apakah aplikasi memang jawaban yang tepat. Rumusan itu memang pendek, tetapi panjang kalimat bukan kelemahan utamanya.', 2),
  (1, 'Catatan pengamatan seorang mahasiswa di meja pengembalian perpustakaan fakultas (rekaan) memuat tiga pernyataan. (i) Antrean pengembalian buku memanjang sampai pintu masuk pada pukul 12.00-13.00. (ii) Petugas mencatat setiap pengembalian dua kali, di buku induk dan di komputer, sehingga satu pengembalian dilayani sekitar empat menit. (iii) Perpustakaan perlu mesin pengembalian mandiri. Pemetaan mana yang tepat untuk ketiga pernyataan itu?', '["(i) masalah, (ii) gejala, (iii) gagasan solusi", "(i) gejala, (ii) gagasan solusi, (iii) masalah", "(i) masalah, (ii) masalah, (iii) gejala", "(i) gejala, (ii) masalah, (iii) gagasan solusi"]'::JSONB, 3, '[C4] Antrean adalah tanda yang terlihat (gejala), pencatatan ganda adalah kondisi di loket yang menjelaskan antrean itu (masalah), dan mesin mandiri adalah usulan produk (solusi). Menyebut antrean sebagai masalah keliru karena antrean baru akibat dari proses pencatatan.', 3),
  (1, 'Kutipan draf proposal: "Penulis memilih angket berskala karena datanya paling mudah diolah dengan aplikasi statistik. Setelah itu, penulis mencari masalah di perpustakaan kampus yang dapat diukur dengan angket, dan terpilih topik kepuasan terhadap ruang baca." Kekeliruan pola pikir mana yang paling tepat menggambarkan kutipan itu?', '["Solutionism, karena penulis melompat ke produk ruang baca sebelum memahami sifat masalahnya", "Method driven research, karena alat analisis dipilih dulu lalu masalah dicari agar cocok dengannya", "Mencampur paradigma, karena penulis memakai angket tanpa menetapkan paradigma utama proyeknya", "Menganggap kualitatif kurang ilmiah, karena penulis menolak wawancara sebagai cara mengumpulkan data"]'::JSONB, 1, '[C4] Urutan dalam kutipan dimulai dari metode (angket) lalu mencari masalah, yang oleh Creswell dan Creswell (2018) disebut method driven research. Solutionism menyangkut lompatan ke solusi atau produk, sedangkan kutipan ini belum membicarakan produk apa pun.', 4),
  (1, 'Satu baris tabel AM-1 berisi isian berikut. Masalah: "Pemustaka tunanetra di perpustakaan kota (rekaan) harus meminta bantuan petugas setiap kali mencari buku karena OPAC tidak terbaca oleh pembaca layar." Paradigma: R&D. Alasan: "Karena R&D paling modern dan hasilnya berupa aplikasi yang canggih." Bagian mana yang paling lemah, dan mengapa?', '["Kolom masalah, karena menyebut OPAC sehingga rumusannya sudah berisi gagasan solusi berupa produk", "Kolom alasan, karena tidak menunjukkan bahwa luaran berupa produk yang menjawab penyebab teramati", "Kolom paradigma, karena masalah pemustaka tunanetra seharusnya diteliti dengan pendekatan kualitatif", "Kolom masalah, karena belum memuat angka persentase pemustaka tunanetra yang meminta bantuan petugas"]'::JSONB, 1, '[C4] Masalahnya sudah berupa kondisi teramati beserta penyebabnya, sehingga R&D masuk akal; yang lemah adalah alasannya, karena "modern" dan "canggih" tidak terkait dengan karakter masalah. Menyebut OPAC bukan solusi, sebab OPAC adalah alat yang sudah ada.', 5),
  (1, 'Rani (rekaan) magang di bagian sirkulasi perpustakaan kampus dan mendapat tugas AM-1 untuk mengamati layanan peminjaman. Rekan sekerjanya sudah diberi tahu tujuan pengamatan dan bersedia diamati. Belakangan kepala bagian, atasan Rani, meminta salinan catatan itu untuk menilai kinerja tiap staf. Menurut kajian Taquette dan Borges da Matta Souza (2022), dilema mana yang paling menonjol dalam situasi itu?', '["Diabaikannya otonomi rekan kerja, karena mereka belum mengetahui tujuan pengamatan yang dilakukan Rani", "Bocornya kerahasiaan unit, karena nama bagian sirkulasi akan tercantum di berkas AM-1 milik Rani", "Potensi kerugian bagi Rani sendiri, karena kepala bagian dapat menilai kinerja magangnya lambat", "Kaburnya peran Rani, karena catatan tugas kuliah bisa menjadi bahan atasan menilai rekan kerjanya"]'::JSONB, 3, '[C4] Rani memegang tiga peran sekaligus (rekan, bawahan, pengamat), dan permintaan atasan mencampur peran pengamat dengan penilaian kinerja. Rekan kerja sudah bersedia diamati, jadi otonomi bukan persoalan utamanya.', 6),
  (1, 'Tim mahasiswa menguji panduan layanan referensi daring di perpustakaan politeknik (rekaan). Dua pustakawan memberi skor rata-rata 3,2 dari 4 pada angket berskala, dan salah satunya menulis: "Istilah subjek dan deskriptor di langkah 2 membingungkan pemustaka baru." Bagaimana kedua jenis data itu sebaiknya dipakai pada tahap pengujian produk?', '["Skor angket menunjukkan tingkat penilaian produk, sedangkan komentar menunjukkan bagian yang perlu diperbaiki", "Skor angket cukup untuk menyatakan produk layak, sedangkan komentar tertulis dilampirkan sebagai pelengkap saja", "Komentar tertulis lebih sahih karena berasal dari ahli, sehingga skor angket tidak perlu dilaporkan lagi", "Kedua data harus diolah dengan statistik agar dapat dibandingkan dengan hasil penelitian kuantitatif lain"]'::JSONB, 0, '[C4] Pada R&D, skor dan komentar dipakai bersama: skor memberi gambaran seberapa baik produk dinilai, komentar memberi arah revisi. Menganggap skor saja sudah cukup akan melewatkan bahan perbaikan yang menjadi ciri perbaikan berulang.', 7),
  (1, 'Laporan akhir proyek repositori di perpustakaan kampus (rekaan) mencantumkan tiga hal: (1) panduan unggah mandiri yang sudah divalidasi dan diuji coba; (2) catatan bahwa petugas tidak memakai fitur pratinjau otomatis karena hasilnya sering berbeda dengan berkas cetak, sehingga mereka tetap membuka berkas satu per satu; (3) daftar hadir pelatihan petugas. Menurut McKenney dan Reeves (2021), mana yang termasuk luaran kedua penelitian pengembangan, yaitu wawasan yang dapat dimanfaatkan pengembang berikutnya?', '["Butir (1), karena panduan yang sudah teruji merupakan bukti keberhasilan proyek", "Butir (3), karena daftar hadir menunjukkan keterlibatan para pemangku kepentingan", "Butir (2), karena menjelaskan fitur yang diabaikan petugas beserta sebabnya", "Butir (1) dan (3), karena keduanya dokumen yang dapat diperiksa oleh pihak lain"]'::JSONB, 2, '[C4] Luaran pertama adalah produk (panduan); luaran kedua adalah pengetahuan tentang cara produk dipakai, misalnya fitur yang diabaikan dan alasannya. Panduan teruji memang penting, tetapi ia luaran pertama, sedangkan daftar hadir hanya bukti administratif.', 8),
  (1, 'Seorang mahasiswa mengamati perpustakaan sekolah dasar (rekaan) yang hanya dijaga dua petugas. Di berkas AM-1 ia menulis: "Petugas A, yang berjaga pada pagi hari dan selalu berkacamata, lebih lambat mencatat peminjaman daripada Petugas B." Nama sekolah ditulis lengkap atas izin kepala sekolah. Penilaian mana yang paling tepat terhadap catatan itu?', '["Kerahasiaan sudah terjaga, karena nama asli petugas sudah diganti dengan kode huruf sesuai pola yang lazim", "Izin belum terpenuhi, karena nama sekolah seharusnya disamarkan meskipun kepala sekolah sudah mengizinkannya", "Kesediaan belum terpenuhi, karena membandingkan dua petugas dalam catatan memerlukan persetujuan tertulis", "Kerahasiaan belum terjaga, karena jam jaga dan ciri fisik tetap menunjuk orang tertentu walau berkode"]'::JSONB, 3, '[C5] Di unit yang hanya berisi dua orang, kode huruf saja tidak menyembunyikan siapa pun, dan keterangan jam jaga serta kacamata membuat identitasnya mudah ditebak. Nama sekolah boleh ditulis bila kepala unit mengizinkan, sesuai Tabel 1.5.', 9),
  (1, 'Dimas (rekaan) mendapat izin kepala perpustakaan dan kesediaan dua petugas untuk mengamati layanan sirkulasi. Di tengah pengamatan, ia ingin merekam video petugas yang sedang melayani agar catatannya lebih lengkap. Tindakan mana yang paling dapat dipertanggungjawabkan secara etis?', '["Langsung merekam, karena kesediaan untuk diamati sudah diberikan dan perekaman sekadar memperjelas catatan yang ada", "Menanyakan lagi kesediaan kedua petugas sebelum merekam dan menjaga agar data pemustaka di layar tidak terekam", "Meminta izin tambahan kepada kepala perpustakaan saja, karena ia yang berwenang atas kegiatan di unit itu", "Merekam dulu, lalu mengaburkan wajah petugas saat menyunting video sehingga identitas mereka tetap tersamarkan"]'::JSONB, 1, '[C5] Persetujuan berkelanjutan berarti kesediaan ditanyakan lagi ketika kegiatan berubah, misalnya dari mengamati menjadi merekam. Mengaburkan wajah sesudah merekam tetap melewati hak petugas untuk menolak.', 10),
  (1, 'Draf latar AM-1 seorang mahasiswa memuat kalimat: "Sebanyak 70% mahasiswa lebih memilih layanan referensi daring daripada datang ke meja referensi (Pratama, 2022)." Rujukan itu ia peroleh dari jawaban ChatGPT. Saat membuka DOI-nya, ia mendapati artikel Pratama (2022) benar-benar ada, tetapi isinya membahas pengelolaan repositori institusi dan tidak memuat angka 70% maupun survei tentang layanan referensi (nama dan artikel rekaan). Tindakan mana yang paling tepat?', '["Menghapus klaim 70% itu dan menulis angka yang benar-benar ditemukan di sumber yang sudah dibaca sendiri", "Mempertahankan klaim itu, karena DOI yang dapat dibuka membuktikan bahwa artikel rujukannya ada dan sah dikutip", "Mempertahankan klaim itu dan menambahkan keterangan bahwa rujukannya diperoleh dari ChatGPT agar tetap jujur", "Mengganti rujukan dengan artikel lain bertema layanan referensi, lalu mempertahankan angka 70% sebagai perkiraan"]'::JSONB, 0, '[C5] DOI yang dapat dibuka membuktikan artikelnya ada, tetapi klaim yang dikutip tetap harus cocok dengan isi artikel; karena itu bab ini meminta mahasiswa membuka sumber sebelum memakai rujukan dari AI. Mengganti rujukan sambil mempertahankan angka yang tidak pernah ditemukan sama dengan mengarang data.', 11),
  (1, 'Karena hujan, Sinta (rekaan) hanya sempat mengamati loket bebas pustaka selama 15 menit dan mencatat tiga pemohon. Agar tabel AM-1 tampak meyakinkan, ia menambahkan "rata-rata waktu tunggu 25 menit dari 20 pemohon" berdasarkan cerita kakak tingkatnya, karena angka itu terdengar wajar. Penilaian mana yang paling tepat terhadap tindakan Sinta?', '["Dapat diterima, karena angkanya wajar dan berasal dari orang yang pernah mengalami layanan itu", "Termasuk plagiarisme, karena Sinta memakai gagasan kakak tingkatnya tanpa mencantumkan rujukan", "Termasuk fabrikasi, karena angka disajikan sebagai hasil pengamatan padahal tidak dicatat sendiri", "Dapat diterima, asalkan Sinta menambahkan catatan bahwa pengamatannya terganggu oleh cuaca"]'::JSONB, 2, '[C5] Data pengamatan harus benar-benar dicatat sendiri; angka yang dikarang termasuk fabrikasi walaupun terdengar wajar. Plagiarisme menyangkut asal kalimat atau gagasan, sedangkan persoalan di sini adalah data yang tidak pernah dikumpulkan.', 12),
  (1, 'Kepala perpustakaan universitas (rekaan) bertanya: "Berapa persen judul e-book langganan kita yang tidak pernah diakses selama tahun 2025?" Tiga mahasiswa berpendapat. Ayu: kuantitatif, karena jawabannya berupa besaran yang dapat dihitung dari log akses. Bima: kualitatif, karena perlu diketahui alasan pemustaka tidak membuka e-book. Citra: R&D, karena hasilnya akan dipakai untuk memperbaiki layanan e-book. Pendapat mana yang paling tepat?', '["Pendapat Ayu, karena pertanyaan itu menanyakan besaran, bukan alasan atau produk", "Pendapat Bima, karena data akses tanpa alasan pemustaka menghasilkan simpulan dangkal", "Pendapat Citra, karena setiap temuan perpustakaan akhirnya dipakai memperbaiki layanan", "Pendapat Bima dan Citra, karena pertanyaan itu baru bermakna bila ada produk perbaikan"]'::JSONB, 0, '[C5] Pertanyaan panduan pertama di bab ini (apakah yang ingin diketahui berupa besaran?) terjawab "ya", sehingga paradigmanya kuantitatif. Alasan pemustaka memang menarik, tetapi itu pertanyaan lain yang tidak diajukan kepala perpustakaan.', 13),
  (1, 'Masalah di layanan surat bebas pustaka perpustakaan kampus (rekaan) dapat dibingkai dua cara. Bingkai pertama dari sisi mahasiswa: surat baru terbit tiga hari setelah diajukan. Bingkai kedua dari sisi petugas: petugas memeriksa tanggungan pinjaman secara manual di dua sistem berbeda. Mahasiswa pengamat dapat menyebar angket kepada pemohon kapan saja, tetapi kepala perpustakaan hanya mengizinkan satu kali wawancara singkat dengan petugas. Bab ini meminta mahasiswa memilih bingkai yang datanya paling mungkin diperoleh dalam satu semester. Menurut aturan itu, bingkai mana yang paling layak dipilih?', '["Bingkai kedua, karena pemeriksaan di dua sistem adalah penyebab yang lebih mendasar daripada waktu tunggu", "Bingkai kedua, karena masalah dari sisi petugas lebih berpengaruh bagi lembaga daripada sisi pengguna", "Kedua bingkai digabung, karena proposal R&D yang baik sebaiknya menjawab kedua sudut pandang sekaligus", "Bingkai pertama, karena datanya paling mungkin dikumpulkan berulang dari pemohon dalam satu semester"]'::JSONB, 3, '[C5] Aturan dalam stimulus menilai bingkai dari ketersediaan data, dan angket kepada pemohon dapat diulang sepanjang semester. Bingkai kedua memang menyentuh penyebab, tetapi satu kali wawancara singkat tidak cukup untuk memahami petugas dan menguji produk bersama mereka.', 14),
  (1, 'Jadwal kerja dalam draf proposal R&D: minggu 1-3 analisis kebutuhan pemustaka perpustakaan sekolah (rekaan) lewat observasi dan wawancara; minggu 4-10 membangun aplikasi katalog daring sampai lengkap; minggu 11-12 menyusun laporan; minggu 13 presentasi akhir. Kritik mana yang paling penting untuk rancangan itu?', '["Analisis kebutuhan terlalu panjang dan sebaiknya dipangkas agar waktu membangun aplikasi lebih lama", "Rancangan belum memuat putaran meminta penilaian lalu memperbaiki produk sebelum laporan disusun", "Rancangan perlu menambahkan uji hipotesis statistik agar hasilnya setara dengan penelitian kuantitatif", "Observasi dan wawancara sebaiknya diganti angket agar data kebutuhan pemustaka lebih mudah diolah"]'::JSONB, 1, '[C5] Ciri ketiga penelitian pengembangan adalah perbaikan berulang: setidaknya satu putaran buat, minta penilaian, perbaiki. Analisis kebutuhan di awal sudah benar, sehingga memangkasnya justru mendekatkan proyek pada solutionism.', 15),
  (1, 'Dalam diskusi kelompok tentang alasan pemustaka lanjut usia di perpustakaan umum kota (rekaan) enggan memakai mesin peminjaman mandiri, seorang anggota berkata: "Kita pakai angket saja. Wawancara itu kurang ilmiah karena tidak menghasilkan angka." Penilaian mana yang paling tepat terhadap pernyataan itu?', '["Benar, karena angket berskala menghasilkan data yang dapat diuji ulang dan dibandingkan antarkelompok", "Keliru, karena wawancara umumnya lebih unggul daripada angket untuk penelitian tentang pemustaka", "Keliru, karena kesahihan pendekatan ditentukan kesesuaiannya dengan masalah yang menanyakan alasan", "Benar sebagian, karena wawancara baru sah bila hasilnya kemudian diubah menjadi persentase jawaban"]'::JSONB, 2, '[C5] Bab ini mencatat anggapan "kualitatif kurang ilmiah" sebagai kesalahan umum; kedua pendekatan sama sah selama sesuai karakter masalah. Pendapat bahwa wawancara umumnya lebih unggul juga keliru karena hanya mengganti satu generalisasi dengan generalisasi lain.', 16),
  (1, 'Petugas layanan referensi perpustakaan umum kabupaten (rekaan) menjawab ratusan pesan WhatsApp setiap bulan. Penghitungan menunjukkan 60% pesan menanyakan jam buka dan syarat menjadi anggota (angka rekaan), dan wawancara mengungkap bahwa informasi itu hanya terpasang di papan pengumuman gedung. Kalimat gagasan produk mana yang paling baik mengikuti pola "[produk] untuk [pengguna] agar [kondisi yang berubah]"?', '["Chatbot kecerdasan buatan untuk perpustakaan umum kabupaten agar layanan referensinya terlihat jauh lebih modern", "Halaman tanya-jawab daring untuk calon anggota agar jam buka dan syarat keanggotaan terjawab tanpa menunggu petugas", "Bagaimana mengurangi jumlah pesan WhatsApp yang harus dijawab oleh petugas layanan referensi setiap bulannya?", "Pelatihan menulis pesan singkat untuk petugas referensi agar balasan WhatsApp mereka menjadi lebih sopan"]'::JSONB, 1, '[C6] Kalimat yang benar menyebut produk, pengguna, dan kondisi yang berubah, serta menjawab sebab yang ditemukan (informasi hanya ada di papan gedung). Kalimat chatbot tidak menyebut pengguna dan kondisinya kabur, sedangkan kalimat tanya adalah rumusan masalah.', 17),
  (1, 'Seorang mahasiswa ingin mengembangkan panduan klasifikasi buku bergambar untuk pustakawan perpustakaan sekolah dasar (rekaan) yang baru bertugas. Rancangan tahapan mana yang paling utuh sebagai penelitian pengembangan?', '["Mengamati dan mewawancarai pustakawan, merancang panduan, meminta penilaian pustakawan senior, merevisi, mencobanya pada dua pustakawan baru, lalu merevisi lagi", "Merancang panduan, meminta penilaian pustakawan senior, merevisi, lalu menyebarkan angket kepuasan kepada pustakawan sekolah dasar di kota itu", "Menyebar angket tentang kesulitan klasifikasi kepada pustakawan, menganalisis hasilnya secara statistik, lalu menulis simpulan dan saran perbaikan", "Mengamati dan mewawancarai pustakawan, merancang panduan, mencetaknya, lalu membagikan panduan itu kepada sekolah dasar di kecamatan tersebut"]'::JSONB, 0, '[C6] Rancangan yang benar memuat ketiga ciri penelitian pengembangan: masalah dipahami lebih dulu, luarannya produk, dan ada putaran penilaian serta perbaikan. Rancangan lain melewatkan analisis masalah, berhenti pada simpulan tanpa produk, atau tidak memuat perbaikan.', 18),
  (1, 'Mahasiswa diminta menyusun satu baris tabel AM-1 (Masalah | Lokasi Pengamatan | Paradigma yang Dipilih | Alasan) dari pengamatan di ruang koleksi tugas akhir perpustakaan kampus (rekaan). Kepala perpustakaan mengizinkan nama unit ditulis. Baris mana yang paling memenuhi ketentuan AM-1?', '["Perpustakaan belum memakai sistem pencarian tugas akhir berbasis kode QR | Ruang Koleksi Tugas Akhir | R&D | Kode QR merupakan teknologi terbaru sehingga cocok untuk proyek pengembangan mahasiswa vokasi", "Pemohon menunggu sekitar 20 menit karena petugas mencari tugas akhir cetak di rak tanpa nomor | Ruang Koleksi Tugas Akhir | Kuantitatif | Waktu tunggu dapat diukur sehingga masalah ini cukup dijawab dengan angka", "Pemohon menunggu sekitar 20 menit karena petugas mencari tugas akhir cetak di rak tanpa nomor | Ruang Koleksi Tugas Akhir | R&D | Penyebab sudah teramati dan hasilnya prosedur penataan rak bagi petugas", "Petugas ruang koleksi tampak kurang ramah dan lambat ketika melayani pemohon | Ruang Koleksi Tugas Akhir | Kualitatif | Sikap petugas perlu digali lewat wawancara agar penyebab keluhan pemohon diketahui"]'::JSONB, 2, '[C6] Baris yang benar menulis masalah sebagai kondisi teramati beserta penyebabnya, dan alasannya memakai pertanyaan panduan ketiga (hasil akhir berupa prosedur yang dipakai orang lain). Baris berparadigma kuantitatif keliru karena besaran dan penyebabnya sudah diketahui.', 19),
  (1, 'Mahasiswa menyusun kalimat keterangan etika untuk akhir berkas AM-1 setelah mengamati layanan referensi di perpustakaan politeknik (rekaan) yang dijaga tiga petugas. Kalimat mana yang paling lengkap dan jujur?', '["Pengamatan dilakukan atas izin kepala perpustakaan; identitas petugas dijamin tidak akan dapat dikenali siapa pun, termasuk oleh rekan sekantor mereka", "Pengamatan dilakukan dengan sepengetahuan ketiga petugas, dan nama mereka ditulis lengkap agar dosen dapat memeriksa kebenaran data di lapangan", "Nama petugas diganti dengan kode Petugas A, B, dan C, dan foto layar komputer layanan yang memuat data pemustaka ditempel sebagai bukti pengamatan", "Pengamatan dilakukan atas izin kepala perpustakaan dan sepengetahuan ketiga petugas; nama petugas diganti kode dan keterangan penunjuk orang dihapus"]'::JSONB, 3, '[C6] Kalimat yang benar mencakup ketiga kewajiban: izin, kesediaan, dan kerahasiaan. Janji anonimitas mutlak tidak jujur karena Subedi (2025) menunjukkan anonimitas mutlak sulit dijamin, sedangkan dua kalimat lain melanggar kerahasiaan.', 20),
  (2, 'Catatan observasi seorang mahasiswa di layanan sirkulasi sebuah perpustakaan umum kota (rekaan) memuat empat baris. Baris 1: "10.05: lima pemustaka antre di mesin peminjaman mandiri, dua di antaranya pindah ke meja petugas". Baris 2: "Mesin peminjaman mandiri tidak ramah pengguna". Baris 3: "10.20: petugas tiga kali memindai ulang buku yang sama". Baris 4: "10.30: papan petunjuk penggunaan mesin tertutup rak pameran". Baris mana yang seharusnya dipindahkan ke kolom tafsiran?', '["Baris 1, karena alasan dua pemustaka pindah ke meja petugas belum diketahui", "Baris 3, karena pemindaian ulang dapat disebabkan banyak hal di luar mesin itu sendiri", "Baris 4, karena letak papan petunjuk belum tentu memengaruhi panjang antrean", "Baris 2, karena berisi penilaian yang tidak dapat diamati atau dihitung langsung"]'::JSONB, 3, '[C4] Baris 2 berupa penilaian ("tidak ramah pengguna"), jadi termasuk tafsiran. Baris 1 memang belum menjelaskan alasan pemustaka pindah, tetapi yang dicatat hanya perilaku yang terlihat lengkap dengan jam dan jumlah, sehingga tetap deskripsi.', 1),
  (2, 'Seorang mahasiswa akan mewawancarai pustakawan layanan referensi di sebuah perpustakaan SMA (rekaan) selama 5 sampai 10 menit. Ia menyiapkan beberapa pertanyaan pembuka. Pertanyaan mana yang paling sesuai dengan prinsip wawancara semiterstruktur pada studi pendahuluan?', '["\"Apakah Ibu setuju jika perpustakaan memakai aplikasi pemesanan buku secara daring?\"", "\"Apakah siswa di sekolah ini sering kesulitan menemukan buku yang mereka cari di rak?\"", "\"Bagian mana dari layanan referensi yang paling sering membuat siswa menunggu lama?\"", "\"Mengapa layanan perpustakaan di sekolah ini kurang baik dibanding sekolah lain?\""]'::JSONB, 2, '[C5] Pertanyaan tentang bagian layanan yang paling sering membuat siswa menunggu bersifat terbuka dan tidak menyodorkan solusi. Pertanyaan tentang kesulitan menemukan buku tampak relevan, tetapi hanya dapat dijawab ya atau tidak, sehingga tidak menggali pengalaman narasumber.', 2),
  (2, 'Data studi pendahuluan tentang unggah mandiri tugas akhir di repositori sebuah perpustakaan kampus (rekaan). Observasi: 3 dari 5 mahasiswa yang mengunggah bertanya kepada petugas di mana lembar persetujuan diunggah. Wawancara petugas: "Yang paling sering itu lupa lembar persetujuan, kadang juga salah format PDF." Rekap penolakan unggahan Mei: 41 penolakan, terdiri atas 29 tanpa lembar persetujuan, 7 karena ukuran berkas, dan 5 karena format. Temuan mana yang paling layak dijadikan bukti utama studi pendahuluan?', '["Kesalahan format PDF, karena disebut langsung oleh petugas yang menangani unggahan", "Ukuran berkas yang terlalu besar, karena tercatat resmi pada rekap penolakan bulanan", "Lembar persetujuan yang tidak dilampirkan, karena muncul pada ketiga sumber data", "Kesalahan format PDF, karena muncul pada wawancara dan rekap penolakan sekaligus"]'::JSONB, 2, '[C4] Lembar persetujuan muncul pada observasi, wawancara, dan dokumen dengan jumlah terbesar, sehingga buktinya paling kuat. Format PDF memang muncul di dua sumber, tetapi jumlahnya kecil dan tidak terlihat saat observasi, jadi buktinya lebih lemah.', 3),
  (2, 'Draf masalah awal seorang mahasiswa: "Di layanan pemesanan ruang diskusi Perpustakaan Institut Kenari (rekaan), banyak kelompok mahasiswa harus kembali keesokan harinya untuk memakai ruang." Masalah awal yang baik memuat empat unsur: tempat atau proses, kejadian yang diamati, ukurannya, dan pihak yang terkena dampak. Unsur mana yang paling jelas belum terpenuhi?', '["Ukuran, karena kata \"banyak\" belum menyebut jumlah yang tercatat di lapangan", "Tempat atau proses, karena tahapan pemesanan ruang diskusi belum dirinci", "Pihak terdampak, karena petugas yang menanggung beban kerja belum disebut", "Kejadian, karena alasan kelompok harus kembali keesokan harinya belum dijelaskan"]'::JSONB, 0, '[C4] Kalimat itu sudah menyebut proses (pemesanan ruang diskusi), kejadian (harus kembali), dan pihak terdampak (kelompok mahasiswa), tetapi "banyak" bukan ukuran. Alasan kelompok harus kembali memang belum ada, namun penyebab diurai pada tahap fishbone, bukan pada kalimat masalah awal.', 4),
  (2, 'Empat mahasiswa menulis masalah awal dari observasi di layanan keanggotaan sebuah perpustakaan umum kabupaten (rekaan). Masalah awal yang baik dapat diamati atau dihitung orang lain, bebas dari nama produk dan kata penilaian, serta sumbernya dapat ditunjuk pada lembar catatan. Rumusan mana yang paling memenuhi ketiga pemeriksaan itu?', '["Layanan keanggotaan perpustakaan kabupaten belum efektif sehingga banyak pemustaka baru merasa kecewa", "Di meja keanggotaan, 6 dari 10 pendaftar selama 40 menit pengamatan diminta kembali membawa fotokopi KTP", "Perpustakaan kabupaten belum memiliki aplikasi pendaftaran anggota secara daring untuk pemustaka baru", "Pendaftaran anggota perpustakaan kabupaten lambat karena petugasnya kurang terlatih dan kurang ramah"]'::JSONB, 1, '[C5] Rumusan tentang 6 dari 10 pendaftar menyebut tempat, kejadian, ukuran, dan sumbernya (pengamatan 40 menit). Rumusan tentang aplikasi pendaftaran terdengar konkret, tetapi menyebut solusi, sehingga tidak dapat diperiksa dari catatan lapangan.', 5),
  (2, 'Masalah awal di perpustakaan sebuah SMP (rekaan): "38 dari 120 pinjaman bulan Maret dikembalikan lewat jatuh tempo (D)". Penyebab yang tercatat: (a) prosedur sirkulasi tidak memuat langkah mengingatkan siswa sebelum jatuh tempo (D); (b) kotak pengembalian hanya dibuka pada jam istirahat sesuai aturan sekolah (O); (c) tinta stempel tanggal kembali di kartu buku mudah luntur sehingga sering tidak terbaca (O, D); (d) pustakawan satu-satunya juga mengajar dua kelas (W). Pengelompokan mana yang tepat menurut empat kategori fishbone pada bab ini?', '["a alat atau teknologi, b metode atau proses, c manusia, d lingkungan atau kebijakan", "a manusia, b lingkungan atau kebijakan, c alat atau teknologi, d metode atau proses", "a metode atau proses, b lingkungan atau kebijakan, c alat atau teknologi, d manusia", "a metode atau proses, b alat atau teknologi, c manusia, d lingkungan atau kebijakan"]'::JSONB, 2, '[C4] Langkah yang tidak ada dalam prosedur termasuk metode, jam buka menurut aturan sekolah termasuk kebijakan, tinta stempel yang luntur termasuk alat, dan beban kerja pustakawan termasuk manusia. Pengecoh yang menaruh kotak pengembalian pada kategori alat keliru karena masalahnya ada pada jam bukanya, bukan pada kotaknya.', 6),
  (2, 'Diagram fishbone untuk masalah "antrean layanan penelusuran skripsi di ruang referensi sebuah perpustakaan kampus (rekaan)" memuat empat cabang: (1) katalog skripsi hanya berupa map daftar judul tercetak (O, W, D); (2) jam layanan ruang referensi ditetapkan rektorat empat jam sehari (D); (3) petugas baru belum hafal susunan rak skripsi (W); (4) mahasiswa tidak tahu skripsi dapat dicari di repositori (W). Cabang mana yang paling tepat dijadikan sasaran proyek satu semester?', '["Jam layanan, karena keputusan rektorat berdampak paling luas bagi pengunjung", "Petugas baru, karena pelatihan petugas paling murah dan paling cepat dilakukan", "Katalog tercetak, karena didukung tiga sumber dan dapat ditangani mahasiswa", "Pengetahuan mahasiswa, karena masalahnya berada pada pengguna layanan"]'::JSONB, 2, '[C5] Cabang katalog tercetak lolos dua cara membaca diagram: buktinya paling kuat dan berada dalam jangkauan proyek. Cabang jam layanan berdampak luas, tetapi ditetapkan rektorat sehingga dicatat sebagai konteks, bukan sasaran proyek.', 7),
  (2, 'Diagram fishbone mahasiswa untuk masalah "buku baru di perpustakaan daerah (rekaan) rata-rata baru dapat dipinjam tujuh minggu setelah diterima (D)" memuat empat cabang. Manusia: "dua pengatalog belum mengikuti pelatihan RDA" (W). Metode: "belum ada aplikasi katalogisasi otomatis". Alat: "printer label sering macet" (O). Lingkungan: "anggaran pembelian buku baru cair pada akhir tahun" (D). Analisis mana yang tepat tentang kekeliruan diagram ini?', '["Cabang lingkungan keliru karena pencairan anggaran berada di luar jangkauan proyek mahasiswa", "Cabang metode keliru karena berisi solusi yang menyamar sebagai penyebab dan tidak bersumber", "Cabang manusia keliru karena baru didukung satu sumber, yaitu wawancara dengan petugas", "Cabang alat keliru karena printer label tidak berkaitan langsung dengan lama pengolahan"]'::JSONB, 1, '[C4] Cabang metode berisi "belum ada aplikasi", yaitu solusi, dan tidak diberi kode sumber, dua kekeliruan yang disebut dalam bab ini. Cabang lingkungan memang di luar jangkauan proyek, tetapi tetap sah dicatat sebagai konteks, jadi bukan kekeliruan.', 8),
  (2, 'Sebuah perpustakaan umum kota (rekaan) ingin membuka layanan antar buku untuk pemustaka lansia. Mahasiswa menulis beberapa rumusan kebutuhan dari hasil wawancara. Rumusan mana yang paling sesuai dengan cara merumuskan kebutuhan sebagai pekerjaan yang ingin diselesaikan?', '["Petugas perlu aplikasi pemesanan antar buku agar pesanan tercatat rapi dan mudah dilacak", "Kepala perpustakaan perlu dasbor statistik layanan antar buku yang diperbarui per bulan", "Relawan pengantar perlu kendaraan dinas supaya buku sampai ke rumah lansia tepat waktu", "Pemustaka lansia perlu mengetahui ketersediaan buku sebelum memesan antar ke rumah"]'::JSONB, 3, '[C5] Rumusan tentang pemustaka lansia menyebut pekerjaan yang ingin diselesaikan tanpa menyebut produk. Rumusan tentang petugas tampak berguna, tetapi "perlu aplikasi" adalah solusi, sehingga belum menjawab apa kebutuhannya.', 9),
  (2, 'Mahasiswa merancang formulir daring usulan pengadaan buku di perpustakaan sebuah fakultas (rekaan). Dosen mengisi usulan di formulir, pustakawan pengadaan memproses usulan di formulir yang sama, wakil dekan bidang keuangan menyetujui anggaran dan uji coba, dan mahasiswa nantinya meminjam buku yang dibeli. Pemetaan mana yang tepat bila pengguna diartikan sebagai pihak yang memakai produk secara langsung?', '["Pengguna: pustakawan pengadaan saja; pemberi izin: dosen; penerima layanan: mahasiswa dan wakil dekan", "Pengguna: mahasiswa peminjam; pemberi izin: pustakawan pengadaan; penerima layanan: dosen pengusul", "Pengguna: dosen, pustakawan, dan wakil dekan; penerima layanan: mahasiswa; pemberi izin: tidak ada", "Pengguna: dosen dan pustakawan pengadaan; pemberi izin: wakil dekan; penerima layanan: mahasiswa"]'::JSONB, 3, '[C4] Dosen dan pustakawan sama-sama memakai formulir secara langsung, wakil dekan menentukan izin, dan mahasiswa menerima hasil layanannya. Pemetaan yang menganggap pustakawan sebagai satu-satunya pengguna melewatkan dosen yang juga mengisi formulir.', 10),
  (2, 'SOP layanan silang layan sebuah perpustakaan kampus (rekaan) menetapkan permintaan salinan artikel dari perpustakaan lain dipenuhi paling lama tiga hari kerja. Register Februari mencatat 14 dari 20 permintaan baru dipenuhi lebih dari lima hari kerja. Kalimat kesenjangan mana yang paling baik?', '["Layanan silang layan artikel seharusnya cepat dan memuaskan, tetapi pemustaka masih sering mengeluh harus menunggu salinan artikel terlalu lama", "SOP menetapkan permintaan artikel dipenuhi dalam tiga hari kerja, tetapi register Februari mencatat 14 dari 20 permintaan selesai lebih dari lima hari", "Layanan silang layan belum memakai sistem pelacakan permintaan daring, sehingga 14 dari 20 permintaan artikel pada Februari terlambat dipenuhi", "Register Februari mencatat 14 dari 20 permintaan salinan artikel dari perpustakaan lain baru dipenuhi petugas lebih dari lima hari kerja setelah diajukan"]'::JSONB, 1, '[C5] Kalimat yang benar memuat kedua sisi beserta sumbernya: acuan dari SOP dan temuan dari register. Kalimat yang hanya mengutip register memang berbukti, tetapi tidak menyebut acuan, sehingga besarnya selisih tidak dapat dinilai.', 11),
  (2, 'Seorang mahasiswa menulis tiga butir identifikasi masalah untuk proposalnya di sebuah perpustakaan daerah (rekaan). Butir 1: "Digitalisasi koleksi lokal perpustakaan daerah." Butir 2: "Belum tersedianya repositori koleksi lokal berbasis web." Butir 3: "Pemustaka merasa koleksi lokal sulit dicari." Analisis kelemahan mana yang paling tepat?', '["Butir 1 baru menyebut bidang, butir 2 menyebut solusi, butir 3 belum menunjukkan bukti", "Butir 1 menyebut solusi, butir 2 belum menunjukkan bukti, butir 3 baru menyebut bidang", "Butir 1 dan 2 sudah tepat, sedangkan butir 3 perlu ditambah angka dari dokumen", "Ketiga butir sudah tepat, tetapi urutannya perlu dimulai dari keluhan pemustaka"]'::JSONB, 0, '[C4] Butir 1 adalah topik yang disangka masalah, butir 2 adalah solusi yang menyamar sebagai masalah, dan butir 3 belum menyebut catatan atau dokumen pendukung. Pengecoh yang menilai butir 2 sudah tepat terkecoh oleh bentuk kalimat "belum tersedianya", padahal yang disebut adalah produk.', 12),
  (2, 'Draf subbab Identifikasi Masalah seorang mahasiswa memuat empat butir dari perpustakaan kampus (rekaan) beserta kode sumbernya: (a) OPAC tidak memuat koleksi tandon (O, W, D); (b) sinyal wifi ruang baca lemah (W); (c) layanan hari Sabtu dihapus oleh kebijakan universitas (D); (d) label punggung buku banyak yang pudar (O, D). Proyeknya hanya akan menangani satu butir. Susunan mana yang paling sesuai?', '["Cantumkan butir a saja, karena butir itulah yang akan ditangani oleh proyek mahasiswa", "Urutkan c, a, d, b, karena kebijakan universitas berdampak paling luas bagi pemustaka", "Urutkan a, d, lalu b dan c; tangani keempat butir agar masalahnya terselesaikan utuh", "Urutkan a, d, lalu b dan c; tandai butir a untuk ditangani; tutup dengan kalimat pembatas"]'::JSONB, 3, '[C5] Butir diurutkan dari bukti terkuat, satu butir ditandai untuk ditangani, dan daftar ditutup dengan kalimat pembatas. Mencantumkan butir a saja tampak ringkas, tetapi pembaca kehilangan gambaran masalah yang utuh.', 13),
  (2, 'Topik usulan seorang mahasiswa: "sistem informasi terpadu untuk seluruh perpustakaan SMA se-kota" (rekaan). Ia baru memegang izin dari satu sekolah, dan pustakawan sekolah itu menyebut katalog kartu yang sulit dicari siswa, yang juga terlihat saat observasi. Kriteria mana yang paling lemah dan langkah apa yang tepat?', '["Keterjangkauan; persempit cakupan menjadi satu proses di satu sekolah, lalu beri skor ulang", "Kebermanfaatan; buang topik karena masalahnya baru disebut oleh satu narasumber di satu sekolah", "Kelayakan; tunda pemberian skor sampai izin dari SMA lain se-kota sudah diperoleh", "Keterjangkauan; buang topik karena skor 1 pada kriteria ini berarti topik tidak layak"]'::JSONB, 0, '[C4] Cakupan se-kota menyangkut banyak unit sehingga keterjangkauannya mendapat skor 1, dan bab ini menyarankan cakupan dipersempit lalu diberi skor ulang. Membuang topik karena skor 1 pada keterjangkauan keliru, sebab topik seperti itu tidak harus dibuang.', 14),
  (2, 'Hasil penyaringan tiga topik di sebuah perpustakaan kampus (rekaan), dengan urutan skor kelayakan, kebermanfaatan, dan keterjangkauan. Topik P, formulir daring usulan judul koleksi baru: 3, 2, 3 (jumlah 8). Topik Q, pengingat jatuh tempo lewat surel: 2, 3, 3 (jumlah 8). Topik R, portal repositori semua fakultas: 2, 3, 1 (jumlah 6). Keputusan mana yang paling tepat?', '["Memilih topik P, karena skor kelayakannya lebih tinggi saat jumlah skornya sama", "Memilih topik Q, karena kebermanfaatan paling menentukan nilai sebuah proyek bagi pengguna", "Memilih topik R, karena manfaatnya paling luas bagi banyak fakultas di kampus", "Menggabungkan topik P dan Q agar dua masalah tertangani dalam satu proyek"]'::JSONB, 0, '[C5] Bila jumlah skor sama, bab ini mendahulukan topik dengan skor kelayakan lebih tinggi karena izin dan data menentukan proyek selesai dalam satu semester. Topik Q unggul di kebermanfaatan, tetapi kriteria itu tidak dipakai sebagai penentu saat jumlah skor sama.', 15),
  (2, 'Topik seorang mahasiswa: "analisis pola peminjaman tiap mahasiswa untuk rekomendasi buku" di sebuah perpustakaan kampus (rekaan). Ia memberi skor 3, 3, 3. Data riwayat pinjam memuat nama dan NIM, sedangkan kepala perpustakaan baru mengizinkan observasi dan belum menyetujui penyalinan data. Penilaian mana yang paling tepat?', '["Skor 3, 3, 3 menunjukkan topik terbaik, sehingga data dapat disalin sambil menunggu izin", "Skor kelayakan cukup diturunkan menjadi 2, lalu topik tetap dapat langsung dipilih", "Nama dan NIM cukup dihapus setelah data disalin, sehingga izin tidak lagi diperlukan", "Topik belum boleh diberi skor sebelum izin data dan keamanan data pribadi dipastikan"]'::JSONB, 3, '[C5] Pemeriksaan etis dilakukan sebelum skor, dan topik yang gagal tidak perlu diberi skor. Menurunkan skor kelayakan tampak wajar karena izin data belum ada, tetapi tidak menjawab soal keamanan data pribadi.', 16),
  (2, 'Mahasiswa menduga anak-anak di pojok baca anak sebuah perpustakaan umum (rekaan) sering kesulitan menemukan buku sesuai jenjang usia. Waktunya terbatas: satu kunjungan 45 menit dan satu wawancara 10 menit. Rancangan pengumpulan data mana yang paling baik?', '["Menyebar angket kepada orang tua pengunjung tentang perlunya aplikasi rekomendasi buku anak, lalu merangkum persentase jawaban yang menyatakan setuju", "Mengamati 45 menit dengan lembar deskripsi dan tafsiran, mewawancarai petugas dengan pertanyaan terbuka, menyalin rekap pinjaman anak dengan izin", "Mewawancarai kepala perpustakaan selama 45 menit tentang rencana pengembangan pojok baca, lalu menulis poin pentingnya seminggu kemudian", "Memotret rak buku anak, lalu menyusun daftar buku yang menurut mahasiswa kurang sesuai jenjang usia sebagai bukti utama masalah"]'::JSONB, 1, '[C6] Rancangan yang memadukan observasi, wawancara singkat, dan dokumen sesuai waktu yang tersedia, sehingga temuannya dapat dicocokkan antarsumber. Rancangan angket kepada orang tua tampak sistematis, tetapi pertanyaannya sudah menyodorkan solusi.', 17),
  (2, 'Data dari layanan sumber elektronik sebuah perpustakaan kampus (rekaan). Rencana kerja unit: 80% pertanyaan tentang akses jurnal daring dijawab dalam satu hari kerja. Rekap surel April: 63 pertanyaan, 22 di antaranya dijawab dalam satu hari kerja. Wawancara pustakawan: "Kalau akses proxy putus, kami harus menunggu vendor." Mahasiswa diminta menyusun satu butir identifikasi masalah berbentuk kalimat kesenjangan. Hasil susunan mana yang paling tepat?', '["Akses proxy jurnal daring sering putus, sehingga perpustakaan perlu sistem pemantauan proxy otomatis agar pertanyaan dijawab cepat", "Rencana kerja menargetkan 80% pertanyaan akses jurnal dijawab dalam sehari, tetapi rekap surel April mencatat hanya 22 dari 63 (35%)", "Pustakawan harus menunggu vendor saat proxy putus, sehingga layanan sumber elektronik dinilai lambat oleh pemustaka kampus", "Rencana kerja menargetkan 80% pertanyaan dijawab dengan cepat, tetapi pemustaka masih banyak yang mengeluh soal akses jurnal"]'::JSONB, 1, '[C6] Butir yang tepat menyandingkan target tertulis dengan angka nyata dari rekap surel, sehingga selisihnya dapat diperiksa. Kutipan pustakawan tentang vendor adalah dugaan penyebab untuk fishbone, bukan bukti kesenjangan.', 18),
  (2, 'Temuan studi pendahuluan di perpustakaan sebuah SMA (rekaan): kartu anggota dicetak manual, dan pada bulan kedua semester 52 dari 80 siswa kelas X belum memiliki kartu (D). Petugas menyebut pencetakan selalu menunggu foto siswa yang dikumpulkan wali kelas (W). Saat istirahat terlihat antrean siswa menanyakan kartunya (O). Rumusan topik proyek satu semester mana yang paling layak, bermanfaat, dan terjangkau?', '["Formulir daring pengumpulan foto dan data siswa baru untuk pencetakan kartu anggota", "Sistem informasi perpustakaan sekolah terpadu dengan modul keanggotaan dan sirkulasi", "Aplikasi kartu anggota digital untuk sekolah se-kabupaten yang terhubung data dinas", "Kajian kepuasan siswa kelas X terhadap berbagai layanan perpustakaan selama satu semester"]'::JSONB, 0, '[C6] Formulir pengumpulan foto menyasar penyebab yang didukung dokumen, wawancara, dan observasi, dan cakupannya satu proses di satu sekolah. Sistem terpadu juga menyentuh keanggotaan, tetapi cakupannya terlalu luas untuk satu semester.', 19),
  (2, 'Catatan lapangan di layanan loker sebuah perpustakaan kampus (rekaan). Observasi pukul 08.00 sampai 08.45: 23 pengunjung meminta kunci loker, 9 ditolak karena loker penuh. Wawancara petugas: "Banyak loker dipakai seharian padahal pemiliknya sudah pulang." Buku kunci loker: selama seminggu, rata-rata 12 kunci tidak dikembalikan pada akhir hari. Masalah awal mana yang paling tepat disusun dari catatan itu?', '["Pengunjung perpustakaan kampus tidak disiplin mengembalikan kunci loker, sehingga mutu layanan loker menjadi buruk setiap harinya", "Perpustakaan kampus belum memiliki loker pintar berbasis kode QR untuk mengatur lama pemakaian loker oleh para pengunjung", "Di layanan loker, 9 dari 23 peminta kunci pada pagi hari ditolak karena penuh, dan rata-rata 12 kunci tidak kembali tiap akhir hari", "Jumlah loker di perpustakaan kampus terlalu sedikit dibanding jumlah pengunjung yang datang setiap pagi pada jam sibuk"]'::JSONB, 2, '[C6] Rumusan tentang 9 dari 23 peminta kunci menyebut proses, kejadian, ukuran, dan pihak terdampak dari dua sumber yang saling menguatkan. Rumusan tentang jumlah loker yang terlalu sedikit terdengar masuk akal, tetapi merupakan tafsiran yang tidak didukung catatan, sebab buku kunci justru menunjukkan loker tertahan oleh pemakai sebelumnya.', 20),
  (3, 'Seorang mahasiswa menulis paragraf latar belakang berikut: "Perpustakaan perguruan tinggi idealnya melayani pemustaka dengan cepat dan tepat. Di Perpustakaan Politeknik Rekaan, pemustaka sering kesulitan menemukan buku di rak karena banyak label nomor panggil yang pudar. Oleh karena itu, proyek ini mengembangkan aplikasi penunjuk letak rak." Unsur alur latar belakang yang belum ada dalam paragraf tersebut adalah ...', '["Kondisi ideal layanan perpustakaan yang menjadi pembanding bagi masalah nyata yang diangkat", "Pernyataan kondisi nyata tentang masalah rak buku di lokasi penelitian mahasiswa", "Data tentang besarnya masalah serta penegasan mengapa masalah itu perlu segera diatasi", "Nama produk dan fitur utama aplikasi yang akan dikembangkan untuk pemustaka"]'::JSONB, 2, '[C4] Paragraf sudah memuat kondisi ideal dan kondisi nyata, lalu melompat ke solusi tanpa data pendukung dan urgensi. Kondisi ideal bukan jawabannya karena kalimat pertama sudah menyatakannya.', 1),
  (3, 'Tiga kalimat dari draf latar belakang proyek katalog daring di Perpustakaan SMA Rekaan (angka rekaan): (1) "Pada Februari 2026, 37 dari 120 siswa yang diamati gagal menemukan buku melalui katalog kartu." (2) "Kemampuan menelusur informasi menjadi kebutuhan dasar siswa sekolah menengah." (3) "Belum tersedia katalog yang dapat dibuka siswa dari ruang kelas." Susunan kalimat yang sesuai dengan pola piramida terbalik beserta alasannya adalah ...', '["(2), (1), (3), karena tulisan bergerak dari isu luas ke data di lokasi lalu ditutup kesenjangan yang menjadi dasar urgensi", "(1), (2), (3), karena data di lokasi perlu didahulukan supaya pembaca sejak awal langsung yakin bahwa masalahnya benar-benar nyata", "(2), (3), (1), karena kesenjangan perlu disebut sebelum data supaya data terbaca sebagai bukti bagi celah tersebut", "(3), (2), (1), karena masalah inti perlu ditulis lebih dulu, baru kemudian didukung isu umum dan data lapangan"]'::JSONB, 0, '[C4] Pola piramida terbalik dimulai dari isu paling luas, menyempit ke data spesifik di lokasi, dan berakhir pada kesenjangan. Mendahulukan angka lokal adalah kesalahan yang disebut bab ini karena pembaca belum tahu mengapa angka itu penting.', 2),
  (3, 'Latar belakang sebuah proposal hanya terdiri atas dua paragraf. Paragraf pertama: "Repositori institusi menjadi sarana penyebaran karya ilmiah kampus dan sudah banyak dibahas peneliti." Paragraf kedua: "Maka proyek ini mengembangkan panduan unggah mandiri untuk repositori Perpustakaan Universitas Rekaan." Bila dianalisis dengan model Create a Research Space (CARS), kelemahan utama latar belakang tersebut adalah ...', '["Langkah memperkenalkan wilayah topik belum muncul karena paragraf pertama belum menyebut nama repositori yang diteliti", "Langkah menempatkan penelitian sendiri belum muncul karena produk yang akan dikembangkan belum disebutkan dengan jelas", "Ketiga langkah sudah muncul, tetapi urutannya terbalik sehingga celah disebut sebelum wilayah topik diperkenalkan", "Langkah menunjukkan celah tidak ada, jadi pembaca tidak tahu apa yang belum tersedia sampai panduan perlu dibuat"]'::JSONB, 3, '[C4] Paragraf pertama memperkenalkan topik dan paragraf kedua menempatkan proyek, tetapi langkah kedua (celah) hilang, sama dengan temuan Samsi (2025). Produk sudah disebut jelas, jadi langkah ketiga sebenarnya ada.', 3),
  (3, 'Rumusan masalah sebuah proposal: "(1) Bagaimana mengembangkan aplikasi peminjaman ruang diskusi untuk mahasiswa di Perpustakaan Universitas Rekaan? (2) Bagaimana kelayakan aplikasi tersebut menurut ahli dan mahasiswa?" Tujuannya: "(1) Meningkatkan minat baca mahasiswa melalui layanan perpustakaan yang modern. (2) Mengetahui kelayakan aplikasi menurut ahli dan mahasiswa." Hasil analisis yang tepat terhadap pasangan rumusan masalah dan tujuan tersebut adalah ...', '["Tujuan (2) tidak selaras karena kelayakan seharusnya diukur dari minat baca mahasiswa sebelum dan sesudah", "Tujuan (1) tidak menjawab rumusan (1) karena menjanjikan minat baca, bukan aplikasi peminjaman ruang diskusi", "Kedua tujuan sudah selaras karena sama-sama menyebut mahasiswa sebagai sasaran utama layanan perpustakaan", "Rumusan masalah (2) sebaiknya digabung ke tujuan (2) karena kelayakan lebih tepat dinyatakan sebagai target"]'::JSONB, 1, '[C4] Tujuan adalah jawaban yang dijanjikan atas tiap rumusan masalah; tujuan (1) melebar ke minat baca yang tidak ditanyakan. Kesamaan sasaran (mahasiswa) tidak membuat tujuan menjawab pertanyaan tentang produk.', 4),
  (3, 'Bagian batasan pada sebuah proposal layanan perpanjangan pinjaman daring di Perpustakaan Daerah Rekaan memuat empat butir: (1) produk hanya mencakup perpanjangan pinjaman, tidak mencakup pembayaran denda; (2) uji coba hanya dilakukan di Perpustakaan Daerah Rekaan; (3) sepuluh responden mundur saat uji coba sehingga data berkurang; (4) pengguna sasaran hanya pemustaka terdaftar. Butir yang tidak tepat ditulis dalam proposal adalah ...', '["Butir (1), karena fitur yang tidak dikerjakan cukup ditulis pada spesifikasi produk, bukan pada bagian batasan", "Butir (3), karena hal itu di luar kendali peneliti, baru diketahui sesudah uji coba, dan dilaporkan di laporan akhir", "Butir (2), karena lokasi uji coba termasuk keterbatasan di luar kendali peneliti yang baru dibahas setelah penelitian selesai", "Butir (4), karena pengguna sasaran sudah ditentukan di rumusan masalah sehingga cukup ditulis di sana"]'::JSONB, 1, '[C4] Batasan dalam proposal adalah keputusan peneliti (delimitations); responden yang mundur adalah limitation yang baru diketahui sesudah uji coba. Lokasi uji coba dipilih sendiri oleh mahasiswa, jadi tetap termasuk batasan proposal.', 5),
  (3, 'Tabel ruang lingkup proyek pencarian koleksi di Perpustakaan Fakultas Rekaan berisi empat baris. Fitur: termasuk pencarian koleksi, tidak termasuk pemesanan buku. Pengguna: termasuk mahasiswa, tidak termasuk dosen. Lokasi: termasuk perpustakaan fakultas, tidak termasuk perpustakaan pusat. Tahap: sampai uji coba terbatas, tidak termasuk penerapan penuh. Kolom alasan pada keempat baris sama, yaitu "karena keterbatasan waktu". Kesimpulan yang tepat dari tabel tersebut adalah ...', '["Tabel sudah baik karena alasan yang seragam memudahkan dosen membaca dan membandingkan batasan antarbaris dengan cepat", "Kolom alasan sebaiknya dihapus karena alasan cukup dijelaskan dalam paragraf manfaat praktis proyek", "Kolom tidak termasuk perlu diisi lebih banyak agar alasan keterbatasan waktu menjadi lebih masuk akal", "Batasan belum dipikirkan per aspek, jadi alasan tiap baris perlu ditarik dari masalah Bab 2 atau akses data"]'::JSONB, 3, '[C4] Bab ini menyebut alasan "keterbatasan waktu" yang diulang di semua baris sebagai tanda batasan belum dipikirkan per aspek. Alasan yang dapat diterima berasal dari masalah yang dipilih atau akses data, bukan dari keseragaman tulisan.', 6),
  (3, 'Judul proposal: "Pengembangan Aplikasi Katalog Daring untuk Mempercepat Penelusuran Koleksi di Perpustakaan SMK Rekaan". Rancangan proyeknya hanya memuat validasi oleh ahli media dan ahli materi, lalu uji coba terbatas kepada 15 siswa memakai angket kelayakan. Proyek ini tidak mengukur waktu penelusuran koleksi. Masalah utama pada judul tersebut adalah ...', '["Kata \"mempercepat\" menuntut pengukuran waktu penelusuran sebelum dan sesudah, padahal rancangan tidak mengukurnya", "Kata \"katalog daring\" perlu diganti \"sistem informasi\" supaya cakupan produk yang dikembangkan tampak lebih luas", "Judul perlu mencantumkan jumlah 15 siswa agar pembaca sampul mengetahui skala uji coba yang direncanakan", "Unsur pengguna belum ada sehingga judul perlu menambahkan kata \"siswa\" setelah frasa penelusuran koleksi"]'::JSONB, 0, '[C4] Kata kerja di judul membawa janji: "mempercepat" berarti waktu proses harus diukur sebelum dan sesudah produk dipakai. Unsur pengguna atau lokasi sudah terpenuhi oleh nama perpustakaan, jadi menambah kata "siswa" tidak menyelesaikan masalah.', 7),
  (3, 'Seorang mahasiswa yang PKL di Perpustakaan SD Rekaan menulis: "Sebuah survei nasional menunjukkan kegemaran membaca masyarakat terus meningkat. Karena itu, siswa di SD Rekaan pasti sudah gemar membaca dan siap memakai pojok baca digital yang akan dikembangkan." Kekeliruan utama penalaran dalam kutipan tersebut adalah ...', '["Data nasional kurang tepat dikutip untuk proyek lokal, sehingga sebaiknya diganti data hasil observasi langsung", "Kalimat kedua sudah benar karena membangun jembatan logis dari isu umum menuju masalah di lokasi yang spesifik", "Angka nasional dianggap berlaku merata di satu sekolah tanpa data dari lokasi itu sendiri sebagai pembanding", "Survei nasional sebaiknya diganti hasil penelitian di SD lain agar pembandingnya lebih setara dengan SD Rekaan"]'::JSONB, 2, '[C4] Bab ini meminta mahasiswa menelusuri data di lokasi PKL dan tidak mengasumsikan angka nasional berlaku merata. Mengganti dengan data SD lain tetap menggeneralisasi dari tempat yang berbeda, dan data nasional masih boleh dipakai sebagai konteks.', 8),
  (3, 'Kalimat lemah dalam draf latar belakang: "Layanan referensi di perpustakaan kurang dimanfaatkan." Empat mahasiswa mengusulkan revisi berdata untuk Perpustakaan Umum Rekaan (angka rekaan). Revisi yang paling tepat sebagai bukti masalah tersebut adalah ...', '["\"Buku tamu Januari-Maret 2026 mencatat 3.200 kunjungan, naik 12% dibanding periode yang sama pada tahun 2025.\"", "\"Laporan pengadaan 2026 mencatat 450 judul buku referensi baru, termasuk 60 judul kamus dan ensiklopedia cetak.\"", "\"Survei Maret 2026 terhadap 80 pemustaka menunjukkan 71% responden puas dengan kenyamanan ruang baca lantai dua.\"", "\"Buku tamu Januari-Maret 2026 mencatat 14 pertanyaan referensi dari 3.200 kunjungan, 9 di antaranya dari pegawai.\""]'::JSONB, 3, '[C5] Keempat revisi berdata, tetapi hanya kunci yang mengukur pemanfaatan layanan referensi, yaitu masalah yang diangkat. Data koleksi referensi baru tampak berkaitan, padahal jumlah koleksi tidak menunjukkan seberapa sering layanan itu dipakai.', 9),
  (3, 'Rumusan masalah sebuah proposal: "Bagaimana mengembangkan modul pelatihan literasi informasi bagi siswa kelas X di Perpustakaan SMA Rekaan?" Rencana proyek mencakup validasi ahli dan uji coba terbatas kepada siswa kelas X. Rumusan tujuan yang paling tepat untuk proposal tersebut adalah ...', '["Meningkatkan budaya literasi warga sekolah melalui program kunjungan perpustakaan yang terjadwal dan berkelanjutan", "Menghasilkan modul pelatihan literasi informasi bagi siswa kelas X yang dinilai layak oleh ahli dan siswa", "Membantu siswa agar lebih mudah memahami informasi dari berbagai sumber yang tersedia di internet", "Mengetahui pendapat guru tentang pentingnya pelatihan literasi informasi bagi siswa kelas X"]'::JSONB, 1, '[C5] Tujuan yang tepat menyebut produk yang dihasilkan, sasarannya, dan ukuran ketercapaian yang sesuai rencana uji. Tujuan tentang budaya literasi seluruh sekolah terlalu luas dan tidak dapat diverifikasi dalam satu proyek.', 10),
  (3, 'Proyek seorang mahasiswa menghasilkan panduan unggah mandiri untuk repositori Perpustakaan Universitas Rekaan, diuji melalui validasi ahli dan uji coba terbatas kepada 12 dosen. Rumusan manfaat teoretis yang paling wajar untuk proyek tersebut adalah ...', '["Menyediakan contoh tahapan pengembangan panduan layanan repositori yang dapat dibandingkan dengan proyek sejenis", "Menghasilkan teori baru tentang perilaku dosen dalam mengunggah karya ilmiah ke repositori institusi kampus", "Bermanfaat bagi kemajuan repositori perguruan tinggi di Indonesia pada masa yang akan datang", "Petugas repositori dapat mengurangi pekerjaan mengunggah karya dosen satu per satu ke sistem repositori kampus"]'::JSONB, 0, '[C5] Manfaat teoretis proyek mata kuliah yang wajar berupa contoh penerapan tahapan pengembangan atau prosedur yang dapat dipakai ulang. Berkurangnya pekerjaan petugas adalah manfaat praktis, bukan teoretis.', 11),
  (3, 'Proposal pengembangan portal koleksi digital di Perpustakaan Politeknik Rekaan memakai istilah kunci "kemudahan akses koleksi digital". Empat mahasiswa menulis definisi operasional untuk istilah itu. Definisi yang paling mendukung penyusunan instrumen pada Bab 6 adalah ...', '["Kemudahan akses adalah keadaan ketika pemustaka merasa nyaman dan senang memakai koleksi digital perpustakaan", "Kemudahan akses merupakan salah satu prinsip utama layanan perpustakaan digital menurut pendapat para ahli", "Kemudahan akses diukur dari jumlah langkah dan menit yang dibutuhkan pemustaka dari laman awal sampai berkas terbuka", "Kemudahan akses berarti koleksi digital dapat dibuka kapan saja dan dari mana saja oleh pemustaka yang sudah terdaftar sebagai anggota"]'::JSONB, 2, '[C5] Definisi operasional menjelaskan cara konsep diukur, sehingga instrumen dapat langsung disusun dari ukurannya. Definisi "dapat dibuka kapan saja" terdengar konkret tetapi tidak menyebut apa yang diukur dan dengan satuan apa.', 12),
  (3, 'Dua mahasiswa menulis kalimat celah untuk layanan surat bebas pustaka daring di Perpustakaan Politeknik Rekaan. Kalimat P: "Aplikasi ini adalah yang pertama di Indonesia untuk layanan bebas pustaka." Kalimat Q: "Sejauh penelusuran penulis di Google Scholar dan Sinta untuk terbitan 2021 sampai 2026 dengan kata kunci bebas pustaka daring, sistem serupa sudah ada di dua perguruan tinggi tetapi belum menampilkan data denda seperti yang dibutuhkan petugas di politeknik ini." Penilaian yang tepat adalah ...', '["Kalimat P lebih tepat karena klaim yang tegas menunjukkan tingkat kebaruan yang lebih tinggi di mata penguji", "Kedua kalimat setara karena sama-sama menyatakan bahwa produk yang akan dikembangkan belum pernah ada", "Kalimat Q lebih tepat karena menyebut batas penelusuran yang dapat diperiksa dan celah sesuai kebutuhan setempat", "Kalimat Q lemah karena mengakui produk serupa sudah ada, sehingga topik proyek tersebut sebaiknya diganti dengan masalah lain"]'::JSONB, 2, '[C5] Klaim kebaruan harus sebanding dengan penelusuran; Q menyebut batas penelusuran dan celah berupa kebutuhan setempat. Produk serupa yang sudah ada tidak membuat proyek gugur selama celahnya digeser ke hal yang memang berbeda.', 13),
  (3, 'Tujuan sebuah proposal: "menghasilkan aplikasi penjadwalan kunjungan kelas ke Perpustakaan SMP Rekaan yang meningkatkan kepuasan guru". Ruang lingkup tahap pengembangan: sampai validasi ahli dan uji coba terbatas kepada empat petugas perpustakaan; guru tidak dilibatkan. Keputusan yang paling tepat untuk proposal tersebut adalah ...', '["Mengubah tujuan atau ruang lingkup, karena tujuan menjanjikan kepuasan guru yang tidak akan diukur dalam proyek", "Mempertahankan keduanya, karena kepuasan guru dapat disimpulkan dari pendapat petugas perpustakaan saat uji coba", "Menghapus kolom tidak termasuk, karena kolom itulah yang membuat tujuan proyek tampak tidak dapat tercapai", "Memindahkan kepuasan guru ke manfaat teoretis, karena manfaat teoretis dapat dinyatakan tanpa data uji coba"]'::JSONB, 0, '[C5] Pemeriksaan pertama sesudah tabel ruang lingkup terisi: tujuan tidak boleh menjanjikan hal yang dinyatakan tidak dikerjakan, jadi salah satunya harus diubah. Pendapat petugas tidak dapat mewakili kepuasan guru yang tidak dilibatkan.', 14),
  (3, 'Tabel spesifikasi produk sebuah proposal berisi: nama produk "SiPinjam"; bentuk aplikasi web; fitur utama pencarian koleksi dan pengajuan pinjaman; pengguna sasaran mahasiswa; tempat dipakai Perpustakaan Universitas Rekaan. Baris batasannya berbunyi "Proyek dikerjakan selama satu semester oleh satu mahasiswa dengan biaya pribadi." Penilaian yang tepat terhadap baris batasan tersebut adalah ...', '["Baris batasan sudah tepat karena waktu dan biaya adalah keterbatasan yang paling ingin diketahui penguji", "Baris batasan kurang tepat karena seharusnya meringkas hal yang tidak termasuk produk, seperti fitur atau pengguna", "Baris batasan tidak diperlukan karena spesifikasi produk cukup memuat lima baris yang sudah terisi lengkap", "Baris batasan perlu diganti definisi operasional karena definisi operasional ditulis pada baris terakhir tabel spesifikasi"]'::JSONB, 1, '[C5] Baris batasan berisi ringkasan kolom "tidak termasuk" dari tabel ruang lingkup, yaitu batas produk. Definisi operasional ditulis di akhir subbab 1.5, bukan sebagai baris tabel spesifikasi.', 15),
  (3, 'Untuk proyek aplikasi pengingat jatuh tempo pinjaman, seorang mahasiswa mengumpulkan tiga data (angka rekaan): (1) laporan sirkulasi Perpustakaan Universitas Rekaan Januari sampai Juni 2026 mencatat 412 dari 2.950 peminjaman terlambat dikembalikan; (2) unggahan media sosial pemustaka yang mengeluh sering lupa tanggal kembali; (3) perkiraan petugas bahwa "kira-kira separuh mahasiswa telat". Penilaian yang tepat terhadap ketiga data tersebut adalah ...', '["Data (3) paling layak karena petugas adalah pihak yang paling memahami keadaan layanan setiap harinya", "Data (2) paling layak karena keluhan langsung pemustaka menunjukkan urgensi masalah yang paling kuat", "Ketiga data setara karena sama-sama berasal dari lokasi penelitian dan menunjukkan masalah yang sama", "Data (1) paling layak sebagai bukti utama karena terukur dan dapat ditelusuri; (2) dan (3) sebatas pelengkap"]'::JSONB, 3, '[C5] Latar belakang yang kuat memakai angka pembanding dari observasi atau laporan resmi dengan sumber yang dapat ditelusuri. Perkiraan petugas berasal dari lokasi yang sama, tetapi berupa taksiran, bukan data yang tercatat.', 16),
  (3, 'Identifikasi masalah (angka rekaan): "Pendaftaran anggota baru di Perpustakaan Daerah Rekaan memakan rata-rata 25 menit karena formulir kertas harus diketik ulang oleh petugas." Mahasiswa akan mengembangkan produk untuk masalah itu. Rancangan rumusan masalah yang paling tepat adalah ...', '["(1) Bagaimana mengembangkan formulir pendaftaran anggota daring untuk Perpustakaan Daerah Rekaan? (2) Bagaimana kelayakan formulir tersebut menurut ahli dan petugas?", "(1) Mengapa pendaftaran anggota baru memakan waktu 25 menit? (2) Siapa yang bertanggung jawab atas pengetikan ulang formulir kertas itu?", "(1) Bagaimana meningkatkan minat masyarakat untuk menjadi anggota Perpustakaan Daerah Rekaan? (2) Bagaimana kepuasan masyarakat terhadap layanan Perpustakaan Daerah Rekaan?", "(1) Menghasilkan formulir pendaftaran anggota daring untuk Perpustakaan Daerah Rekaan. (2) Mengetahui kelayakan formulir menurut ahli dan petugas."]'::JSONB, 0, '[C6] Penelitian pengembangan lazim memakai dua pertanyaan: satu tentang produk dan satu tentang kelayakannya. Pasangan kalimat "Menghasilkan ... Mengetahui ..." isinya benar, tetapi berbentuk tujuan, bukan pertanyaan.', 17),
  (3, 'Data observasi (angka rekaan): menelusuri satu skripsi di repositori Perpustakaan Universitas Rekaan rata-rata butuh 12 menit karena metadata banyak yang tidak lengkap. Mahasiswa akan mengembangkan panduan pengisian metadata untuk petugas, lalu menjalankan validasi ahli dan uji coba terbatas yang mengukur waktu penelusuran sebelum dan sesudah panduan dipakai. Rumusan tujuan yang paling tepat disusun mahasiswa adalah ...', '["Meningkatkan kualitas repositori universitas agar mampu bersaing dan dikenal luas di tingkat nasional maupun internasional", "Membuat panduan untuk membantu petugas dan mahasiswa supaya repositori menjadi lebih baik dan mudah", "Mengetahui penyebab metadata skripsi tidak lengkap di repositori Perpustakaan Universitas Rekaan", "Menghasilkan panduan pengisian metadata bagi petugas yang menurunkan waktu penelusuran dari 12 menjadi di bawah 5 menit"]'::JSONB, 3, '[C6] Tujuan yang terukur menyebut produk, penggunanya, dan perubahan yang dapat diverifikasi sesuai rencana uji. Mencari penyebab metadata tidak lengkap adalah tujuan penelitian deskriptif, bukan tujuan proyek pengembangan.', 18),
  (3, 'Unsur proyek seorang mahasiswa: produk berupa aplikasi pengingat jatuh tempo pinjaman; masalah berupa keterlambatan pengembalian buku; lokasi Perpustakaan Universitas Rekaan; rancangan mengukur jumlah keterlambatan sebelum dan sesudah aplikasi dipakai. Istilah "aplikasi pengingat" dipakai di seluruh rumusan masalah. Judul yang paling tepat disusun dari unsur tersebut adalah ...', '["\"Aplikasi SIPENTA: Inovasi Digital Pertama untuk Perpustakaan Modern di Era Revolusi Industri\"", "\"Pengembangan Aplikasi Pengingat Jatuh Tempo untuk Mengurangi Keterlambatan Pengembalian Buku di Perpustakaan Universitas Rekaan\"", "\"Pengembangan Sistem Informasi Perpustakaan untuk Meningkatkan Kepuasan Layanan Sirkulasi dan Minat Baca Mahasiswa Perguruan Tinggi di Indonesia\"", "\"Pengembangan Aplikasi Pengingat di Perpustakaan Universitas Rekaan Berbasis Teknologi Informasi Terkini\""]'::JSONB, 1, '[C6] Judul memuat kata Pengembangan, nama produk, masalah, dan lokasi, dengan istilah produk yang sama seperti di rumusan masalah; kata "mengurangi" sesuai karena keterlambatan diukur. Judul tanpa unsur masalah tidak memberi tahu untuk apa produk dibuat.', 19),
  (3, 'Masalah yang dipilih seorang mahasiswa pada Bab 2 hanya lamanya pengolahan buku baru di Perpustakaan SMP Rekaan, dan izin akses data hanya ia peroleh di perpustakaan sekolah itu. Ia menyusun baris "Fitur produk" pada tabel ruang lingkup. Rancangan baris yang paling tepat adalah ...', '["Termasuk: layanan pengolahan dan sirkulasi buku. Tidak termasuk: layanan referensi. Alasan: agar produk bermanfaat seluas mungkin.", "Termasuk: isian data bibliografis. Tidak termasuk: layanan peminjaman. Alasan: karena keterbatasan waktu pengerjaan proyek.", "Termasuk: isian data bibliografis dan cetak label nomor panggil. Tidak termasuk: layanan sirkulasi. Alasan: masalah Bab 2 hanya lamanya pengolahan buku baru.", "Termasuk: isian data bibliografis dan layanan peminjaman. Tidak termasuk: cetak label nomor panggil. Alasan: izin akses data diperoleh di perpustakaan sekolah tempat PKL."]'::JSONB, 2, '[C6] Baris yang baik menyebut yang termasuk, yang tidak termasuk, dan alasan yang ditarik dari masalah Bab 2. Alasan "keterbatasan waktu" bersifat umum dan tidak menjelaskan mengapa fitur tertentu dikeluarkan.', 20),
  (4, 'Seorang mahasiswa mengembangkan sistem pemesanan ruang diskusi di perpustakaan kampus rekaan. Ia mengumpulkan empat sumber: (1) buku teks desain layanan dari penerbit akademik, (2) artikel jurnal Sinta 2 tentang sistem reservasi ruang di perpustakaan universitas lain, (3) peraturan kepala perpustakaan tentang jam layanan ruang diskusi, dan (4) unggahan forum tanpa nama penulis tentang aplikasi reservasi. Pemetaan keempat sumber ke jenis sumber kajian pustaka penelitian pengembangan menurut Sugiyono (2019) yang paling tepat adalah ...', '["(1) teori dasar, (2) data atau kebijakan pendukung, (3) penelitian sejenis, (4) praktik baik dari lapangan", "(1) penelitian sejenis, (2) teori dasar, (3) data atau kebijakan pendukung, (4) data pendukung tambahan", "(1) teori dasar, (2) penelitian sejenis, (3) data atau kebijakan pendukung, (4) tidak layak dirujuk", "(1) teori dasar, (2) penelitian sejenis, (3) praktik baik industri, (4) penelitian sejenis yang informal"]'::JSONB, 2, '[C4] Buku teks memberi teori dasar, artikel jurnal adalah hasil penelitian sejenis, dan peraturan termasuk kebijakan pendukung. Unggahan forum tanpa penulis jelas berkredibilitas rendah, jadi tidak tepat dihitung sebagai jenis sumber apa pun.', 1),
  (4, 'Mahasiswa mencari penelitian sejenis untuk chatbot layanan referensi perpustakaan. Di Garuda ia mengetik frasa bertanda kutip "pengembangan chatbot layanan referensi berbasis WhatsApp di perpustakaan perguruan tinggi" dan memperoleh nol hasil. Ia lalu mengetik chatbot OR perpustakaan dan memperoleh ribuan hasil yang kebanyakan membahas toko daring (angka rekaan). Analisis yang paling tepat tentang sebab kedua penelusuran itu gagal adalah ...', '["Frasa panjang bertanda kutip menuntut susunan kata persis, sedangkan OR menerima artikel dengan salah satu kata", "Garuda kurang lengkap untuk topik teknologi, sehingga penelusuran sebaiknya dipindah ke mesin pencari umum", "Kata kuncinya berbahasa Indonesia, padahal penelitian chatbot lebih banyak terbit dalam bahasa Inggris", "Kedua rangkaian terlalu pendek, sehingga hasilnya akan membaik bila ditambah kata lain tanpa mengubah operatornya"]'::JSONB, 0, '[C4] Tanda kutip pada frasa panjang hanya menemukan artikel dengan susunan kata yang persis sama, dan OR memperluas hasil ke artikel yang memuat satu kata saja. Kata kunci berbahasa Inggris memang dapat menambah hasil, tetapi tidak menjelaskan hasil nol dan hasil yang tidak relevan; perbaikannya AND antarkonsep dan OR untuk sinonim.', 2),
  (4, 'Dua mahasiswa mengembangkan produk untuk perpustakaan SD mitra di Kabupaten Wiyata (rekaan) dan butuh data tentang rendahnya kunjungan. Mahasiswa P memakai laporan tahunan dinas perpustakaan kabupaten yang mencatat rata-rata kunjungan seluruh perpustakaan sekolah di kabupaten itu. Mahasiswa Q memakai laporan tahunan perpustakaan SD mitra yang mencatat kunjungan per bulan selama dua tahun. Penilaian yang paling tepat tentang pemakaian kedua sumber di latar belakang proposal adalah ...', '["Data dinas lebih tepat menjadi data utama karena cakupannya lebih luas, sehingga laporan SD cukup ditaruh di lampiran", "Laporan SD lebih tepat, dan data dinas sebaiknya ditinggalkan karena rata-rata kabupaten dapat menutupi kondisi sekolah", "Kedua laporan setara sebagai data utama karena sama-sama resmi, sehingga mahasiswa cukup memakai salah satunya", "Laporan SD mitra paling tepat menunjukkan masalah di lokasi proyek, dan data dinas menguatkan bahwa masalahnya meluas"]'::JSONB, 3, '[C5] Data yang langsung menggambarkan lokasi proyek paling kuat untuk menunjukkan masalah, sedangkan data lembaga di atasnya memberi konteks yang lebih luas. Rata-rata kabupaten memang dapat menutupi kondisi satu sekolah, tetapi justru berguna sebagai pembanding, bukan alasan untuk membuangnya.', 3),
  (4, 'Kalimat sumber (rekaan): "Pengingat otomatis melalui pesan singkat terbukti menurunkan keterlambatan pengembalian buku karena pemustaka menerima peringatan tepat sebelum tenggat." Versi 1: "Pengingat otomatis lewat pesan singkat terbukti mengurangi keterlambatan pengembalian buku sebab pemustaka mendapat peringatan persis sebelum tenggat (Sari, 2022)." Versi 2: "Pemustaka yang diberi tahu menjelang batas waktu cenderung mengembalikan buku tepat waktu, sehingga pesan dari sistem dapat menekan angka keterlambatan (Sari, 2022)." Versi 3 sama dengan Versi 2 tetapi tanpa (Sari, 2022). Penilaian yang paling tepat adalah ...', '["Versi 1 dan Versi 2 sahih karena keduanya mencantumkan nama penulis dan tahun terbit sumbernya", "Yang sahih Versi 2, karena struktur dan katanya berubah, maknanya tetap, dan sumbernya disebut", "Versi 2 dan Versi 3 sahih karena keduanya sudah ditulis ulang dengan kalimat mahasiswa sendiri", "Versi 1 paling sahih karena maknanya paling dekat dengan kalimat sumber dan kutipannya sudah lengkap"]'::JSONB, 1, '[C5] Versi 1 hanya menukar sinonim dengan struktur yang sama, jadi tergolong patchwriting meski berkutipan. Versi 3 sudah parafrase, tetapi tanpa kutipan tetap plagiarisme.', 4),
  (4, 'Draf kajian teori proyek katalog daring perpustakaan umum: "Menurut Andi (2020), katalog daring memudahkan pencarian koleksi. Menurut Budi (2021), katalog daring mempercepat temu kembali. Menurut Citra (2022), sebagian pemustaka lanjut usia kesulitan memakai katalog daring." (nama rekaan). Kelemahan utama paragraf itu dan perbaikan yang paling tepat adalah ...', '["Paragraf kekurangan sumber; perbaikannya menambah dua penulis lagi dengan pola kalimat yang sama", "Paragraf sekadar menderetkan pendapat; Andi dan Budi disatukan sebagai temuan sejalan, Citra temuan berbeda", "Paragraf terlalu banyak parafrase; perbaikannya mengganti tiap kalimat dengan kutipan langsung yang bertanda petik", "Paragraf tidak urut tahun; perbaikannya menyusun ulang sumber dari tahun terbaru ke tahun terlama"]'::JSONB, 1, '[C4] Pola "Menurut A, menurut B" adalah kumpulan kutipan, bukan sintesis. Sintesis mengelompokkan temuan yang sepakat dan menonjolkan temuan yang berbeda karena di situlah celah muncul; menambah sumber dengan pola sama tidak memperbaiki masalahnya.', 5),
  (4, 'Matriks sintesis proyek layanan antar buku perpustakaan umum kabupaten (rekaan). Baris kebutuhan pemustaka desa: Sumber A, B, dan C sepakat jarak menjadi hambatan. Baris biaya operasional: hanya Sumber D. Baris kepuasan pengguna: Sumber B melaporkan pengguna puas, Sumber E melaporkan keluhan keterlambatan. Baris layanan antar bagi penyandang disabilitas: belum ada sumber. Kesimpulan yang paling tepat dari matriks itu adalah ...', '["Tema kebutuhan paling lemah karena sumbernya menyampaikan hal yang sama sehingga tidak memberi bahan perdebatan", "Tema disabilitas sebaiknya dihapus dulu karena tema tanpa sumber belum dapat ditulis menjadi paragraf", "Tema kepuasan sudah tuntas karena memuat dua sumber yang berbeda tahun terbit dan berbeda penulis", "Tema biaya perlu ditelusuri lagi, tema kepuasan berbeda temuan, tema disabilitas menunjukkan celah"]'::JSONB, 3, '[C4] Baris dengan satu sumber menandakan tema itu perlu ditelusuri lagi, sedangkan temuan berbeda dan tema tanpa sumber menunjukkan celah. Tema tanpa sumber justru dipertahankan karena dapat menjadi alasan proyek.', 6),
  (4, 'Proyek mahasiswa: aplikasi katalog daring untuk perpustakaan SMK. Satu entri tabel penelitian yang relevan berbunyi: Peneliti: Hartono (2023, rekaan). Temuan kunci: katalog daring di perpustakaan SMA menaikkan kunjungan. Persamaan: sama-sama penelitian tentang perpustakaan. Perbedaan: penelitian Hartono dilakukan pada tahun 2023. Penilaian yang paling tepat atas entri itu adalah ...', '["Kolom persamaan dan perbedaan terlalu umum; sebutkan jenis produk yang sama dan hal baru seperti pengguna SMK", "Entri sudah memadai karena keempat kolom terisi dan nama peneliti serta tahunnya ditulis lengkap", "Kolom temuan sebaiknya dihapus karena tabel penelitian yang relevan cukup memuat kolom persamaan dan perbedaan", "Kolom perbedaan sudah tepat karena tahun yang berbeda menunjukkan kebaruan proyek mahasiswa"]'::JSONB, 0, '[C5] Persamaan seharusnya berupa masalah, jenis produk, model, atau pengguna yang serupa, dan perbedaan adalah hal yang dikerjakan proyek tetapi belum dikerjakan penelitian itu. Tahun terbit bukan perbedaan yang membenarkan proyek.', 7),
  (4, 'Kerangka berpikir proyek repositori skripsi perpustakaan kampus (rekaan) terdiri atas empat kotak berpanah dari kiri ke kanan. Masalah: pemustaka sulit menemukan skripsi. Teori dan penelitian: teori kepuasan kerja karyawan. Produk: repositori skripsi dengan pencarian berdasarkan subjek. Hasil: pemustaka menemukan skripsi lebih cepat. Penilaian yang paling tepat atas kerangka itu adalah ...', '["Kerangka sudah benar karena keempat kotak terisi dan panahnya mengarah dari kiri ke kanan sesuai alur bacanya", "Kotak hasil perlu diubah karena hasil yang diharapkan sebaiknya dinyatakan dalam angka persentase", "Kotak teori tidak menghubungkan masalah dan produk; isinya perlu diganti teori temu kembali informasi", "Kotak masalah perlu dipindah ke kanan karena kerangka dibaca dari hasil menuju masalah"]'::JSONB, 2, '[C5] Setiap kotak harus dapat ditelusuri ke bagian proposal, dan kotak teori diisi dari tema kajian teori yang menjelaskan produk. Teori kepuasan kerja karyawan tidak menjelaskan mengapa pencarian berdasarkan subjek memecahkan masalah temu kembali.', 8),
  (4, 'Pembimbing memeriksa kajian pustaka proposal layanan literasi informasi di perpustakaan sekolah dan menemukan tiga hal. (1) Satu paragraf parafrase yang rapi dari sebuah buku, tanpa nama penulis. (2) Kutipan (Lee, 2015) yang disalin dari daftar pustaka artikel lain, padahal mahasiswa belum pernah membaca karya Lee. (3) Bunyi pasal peraturan perpustakaan yang dikutip langsung dengan tanda petik dan nomor pasalnya. Analisis yang paling tepat atas ketiga temuan itu adalah ...', '["Temuan 1 dan 2 tergolong plagiarisme yang mudah luput, temuan 3 kutipan langsung yang sah", "Temuan 2 bermasalah, sedangkan temuan 1 dapat diterima karena sudah ditulis ulang dengan kalimat sendiri", "Ketiga temuan bermasalah karena kutipan langsung sebaiknya dihindari di dalam kajian pustaka", "Temuan 1 bermasalah, sedangkan temuan 2 dapat diterima karena nama penulis dan tahunnya dicantumkan"]'::JSONB, 0, '[C4] Parafrase tanpa kutipan dan kutipan atas sumber yang tidak dibaca adalah dua bentuk plagiarisme yang sering luput dari penulisnya. Kutipan langsung dibenarkan untuk bunyi pasal peraturan karena susunan kata aslinya memang diperlukan.', 9),
  (4, 'Pemeriksa kemiripan memberi angka 8% untuk proposal A dan 27% untuk proposal B (angka rekaan). Pada proposal B, sebagian besar kemiripan berasal dari daftar rujukan dan istilah baku seperti repositori institusi dan metadata Dublin Core. Pada proposal A, mahasiswa menjalankan seluruh kajian teori lewat alat parafrase otomatis dan tidak mencantumkan sumber. Penilaian yang paling tepat adalah ...', '["Proposal B lebih bermasalah karena kemiripan di atas 20% umumnya menandakan banyak bagian yang disalin langsung", "Kedua proposal aman karena alat parafrase dan istilah baku sama-sama mengubah kalimat sumber", "Proposal A lebih bermasalah karena keluaran alat parafrase tetap gagasan orang lain yang perlu dikutip", "Proposal A aman karena angka 8% sudah membuktikan bahwa parafrase mahasiswa sahih dan asli"]'::JSONB, 2, '[C5] Angka rendah tidak membuktikan parafrase sahih, dan angka tinggi bisa berasal dari daftar rujukan atau istilah baku. Hasil alat parafrase otomatis tetap gagasan sumber sehingga tanpa kutipan tetap plagiarisme.', 10),
  (4, 'Daftar rujukan yang diimpor otomatis oleh pengelola referensi memuat tiga entri ini (contoh rekaan). Entri 1: Statistik, B. P. (2023). Statistik perpustakaan sekolah. Entri 2: Sugiyono, S. (2019). Metode penelitian & pengembangan. Entri 3: Hartono, A. (2021). PERPUSTAKAAN DIGITAL DI SEKOLAH MENENGAH. Diagnosis yang paling tepat atas kesalahan ketiga entri itu adalah ...', '["Ketiganya terjadi karena gaya sitasi di pengaya Word belum disetel ke APA edisi ke-7 sejak awal penulisan", "Penulis lembaga terbaca sebagai nama orang, nama satu kata dipenggal, dan judul kapital belum diubah", "Ketiganya terjadi karena sumber dimasukkan lewat DOI, yang sering tidak membawa data nama penulis", "Kesalahan terletak pada judul kapital, sedangkan nama penulis sudah sesuai data yang ditarik aplikasi"]'::JSONB, 1, '[C4] Data yang ditarik otomatis perlu diperiksa: penulis lembaga harus diisi sebagai nama lembaga, nama satu kata dapat terpenggal, dan judul berhuruf kapital perlu diubah ke huruf kalimat. Mengganti gaya sitasi tidak memperbaiki data yang salah sejak diimpor.', 11),
  (4, 'Gabungan tiga bab proposal memuat 24 sumber. Mahasiswa K mengetik daftar rujukan dengan tangan setelah semua bab selesai. Mahasiswa L memasukkan tiap sumber ke Mendeley pada hari menemukannya, menyisipkan kutipan lewat pengaya Word, lalu mencocokkan beberapa entri dengan sumber aslinya. Mahasiswa M memakai Mendeley, tetapi mengetik kutipan di naskah dengan tangan agar cepat. Praktik dengan risiko kesalahan rujukan paling kecil adalah ...', '["Praktik K, karena daftar yang diketik di akhir memuat sumber yang benar-benar final dan sudah terpakai", "Praktik M, karena aplikasi tetap menyimpan data sumber walaupun kutipannya diketik tangan", "Praktik K dan M setara dengan L selama gaya yang dipakai sama-sama APA edisi ke-7", "Praktik L, karena tiap kutipan punya pasangan di daftar rujukan dan data impornya tetap diperiksa"]'::JSONB, 3, '[C5] Kutipan yang disisipkan lewat pengaya selalu tersambung ke daftar rujukan, dan pemeriksaan entri menangkap data impor yang salah. Kutipan ketik tangan pada praktik M memutus sambungan itu sehingga selisih tahun atau sumber yang hilang tetap bisa terjadi.', 12),
  (4, 'Mahasiswa akan mengembangkan pojok baca digital di perpustakaan desa (rekaan). Sejauh ini ia mengambil artikel dari halaman pertama mesin pencari, lalu menyesuaikan argumennya dengan apa yang kebetulan ditemukan. Rancangan langkah penelusuran yang paling tepat untuk ia susun adalah ...', '["Baca artikel di halaman pertama hasil pencarian dengan teliti, lalu pilih sumber yang paling mendukung argumen", "Kumpulkan sebanyak mungkin sumber dari berbagai mesin pencari, lalu tetapkan kriteria setelah draf rampung", "Batasi pencarian pada satu jurnal Scopus ternama agar sumbernya kredibel tanpa perlu banyak penyaringan", "Tetapkan kata kunci dan kriteria, cari luas di Google Scholar dan Garuda, saring, lalu dalami sisanya"]'::JSONB, 3, '[C6] Penelusuran yang direncanakan dimulai dari kata kunci dan kriteria, lalu bergerak dari pencarian luas ke penyaringan dan pendalaman. Membatasi pada satu jurnal memang menjamin kredibilitas, tetapi membuang banyak penelitian relevan.', 13),
  (4, 'Satu baris matriks sintesis proyek perpustakaan kampus (rekaan). Tema: jam layanan ruang baca. Analisis sumber: Sumber A menyebut mahasiswa membutuhkan ruang baca pada malam hari menjelang ujian; Sumber C melaporkan kenaikan kunjungan di perpustakaan yang membuka layanan 24 jam. Pola: saling melengkapi. Kaitan dengan proyek: produk menyediakan pemesanan kursi ruang baca malam. Kalimat topik paragraf sintesis yang paling tepat disusun dari baris itu adalah ...', '["Menurut Sumber A, mahasiswa butuh ruang baca malam. Menurut Sumber C, layanan 24 jam menaikkan kunjungan.", "Kebutuhan ruang baca malam (A) sejalan dengan naiknya kunjungan layanan 24 jam (C), jadi akses malam layak dibuka.", "Jam layanan perpustakaan kampus sangat beragam di berbagai negara dan terus berkembang dari waktu ke waktu.", "Sumber A dan Sumber C saling bertentangan tentang jam layanan, sehingga proyek ini hadir untuk menengahi keduanya sekaligus."]'::JSONB, 1, '[C6] Kalimat topik sintesis memadukan kedua sumber sesuai pola pada kolom ketiga dan mengarah ke kaitan dengan proyek. Kalimat "Menurut A... Menurut C..." masih berupa deretan kutipan, dan pola yang tercatat adalah saling melengkapi, bukan bertentangan.', 14),
  (4, 'Data rekaan jumlah artikel tentang repositori institusi di jurnal nasional: 2020 ada 4, 2021 ada 5, 2022 ada 5, 2023 ada 14, dan 2024 ada 15. Seorang mahasiswa menulis di kajian pustakanya: "Topik repositori institusi tidak lagi menarik karena publikasinya sudah banyak." Analisis yang paling tepat atas data dan kalimat itu adalah ...', '["Data menunjukkan topik mulai stagnan karena dari 2023 ke 2024 jumlahnya bertambah satu artikel", "Data kurang tepat dipakai karena tren publikasi lebih cocok untuk kajian bibliometrik daripada untuk proposal", "Ada lonjakan sejak 2023, tanda topik sedang diperhatikan, sehingga data ini memperkuat argumen relevansi", "Data menunjukkan celah proyek makin sempit karena aspek repositori sudah banyak diteliti orang"]'::JSONB, 2, '[C4] Jumlah artikel hampir tiga kali lipat dari 2022 ke 2023 lalu bertahan tinggi, tanda topik sedang aktif diteliti. Tren seperti ini dipakai sebagai bukti relevansi, sedangkan kenaikan kecil 2023 ke 2024 tidak menghapus lonjakan sebelumnya.', 15),
  (4, 'Mahasiswa menyusun subbab kajian teori literasi informasi untuk modul pelatihan pemustaka di perpustakaan SMK. Kandidat rujukan definisinya: (1) buku teks literasi informasi dari penerbit akademik terbitan 2012; (2) artikel jurnal Sinta 2 tahun 2024 yang meneliti literasi informasi siswa di satu SMK dan memakai definisi dari buku itu; (3) artikel konferensi 2023 tentang literasi digital mahasiswa yang merumuskan definisi literasi informasi versinya sendiri. Keputusan rujukan yang paling dapat dipertanggungjawabkan adalah ...', '["Definisi diambil dari buku (1), dan artikel (2) dipakai sebagai penelitian sejenis pada siswa SMK", "Definisi diambil dari artikel (2) karena lebih baru dan berkonteks SMK, dan buku (1) dikutip lewat artikel itu", "Definisi diambil dari artikel (3) karena literasi digital lebih dekat dengan modul pelatihan yang berbasis teknologi", "Definisi dirangkai dari ketiga sumber secara berurutan agar subbab teori tampak bertumpu pada lebih banyak rujukan"]'::JSONB, 0, '[C5] Buku teks dari penerbit akademik tepat untuk definisi konsep dasar, sedangkan artikel (2) bernilai sebagai penelitian sejenis. Mengutip buku lewat artikel (2) berarti mengutip sumber yang tidak dibaca langsung, dan artikel (3) membahas konsep yang berbeda.', 16),
  (4, 'Proyek mahasiswa: aplikasi pinjam antarperpustakaan untuk tiga perpustakaan SMK di satu kota, diuji dengan uji kegunaan bersama siswa. Penelitian yang relevan: Wibowo (2022, rekaan) membangun sistem pinjam antarperpustakaan untuk perpustakaan universitas dan hanya mengujinya dengan uji fungsional black box. Rumusan kolom perbedaan yang paling tepat untuk tabel penelitian yang relevan adalah ...', '["Proyek ini dan penelitian Wibowo sama-sama mengembangkan sistem pinjam antarperpustakaan berbasis aplikasi", "Proyek ini dikerjakan pada tahun yang lebih baru sehingga teknologinya lebih mutakhir daripada Wibowo", "Proyek ini menyasar perpustakaan SMK dan menguji kegunaan, sedangkan Wibowo menyasar universitas dan menguji fungsi", "Proyek ini lebih unggul daripada penelitian Wibowo karena dikembangkan oleh mahasiswa Perpustakaan Digital"]'::JSONB, 2, '[C6] Kolom perbedaan memuat hal yang dikerjakan proyek tetapi belum dikerjakan penelitian itu, yaitu pengguna dan cara menguji. Kalimat "sama-sama mengembangkan" adalah isi kolom persamaan, bukan perbedaan.', 17),
  (4, 'Bab 1 proposal mencatat masalah: pemustaka perpustakaan umum kota (rekaan) tidak tahu koleksi baru karena pengumumannya hanya ditempel di papan. Kajian teorinya memuat tema layanan informasi terbaru dan dua penelitian tentang notifikasi koleksi baru. Produknya aplikasi notifikasi koleksi baru, dan tujuannya agar pemustaka mengetahui koleksi baru dalam satu minggu. Susunan empat kotak kerangka berpikir yang paling tepat adalah ...', '["Pengumuman tidak menjangkau pemustaka, lalu teori layanan informasi terbaru dan dua penelitian, lalu aplikasi notifikasi, lalu pemustaka tahu koleksi baru dalam seminggu", "Aplikasi notifikasi, lalu pengumuman tidak menjangkau pemustaka, lalu teori layanan informasi terbaru, lalu pemustaka tahu koleksi baru", "Pengumuman tidak menjangkau pemustaka, lalu teori manajemen keuangan perpustakaan, lalu aplikasi notifikasi, lalu pemustaka tahu koleksi baru", "Pengumuman tidak menjangkau pemustaka, lalu teori layanan informasi terbaru dan dua penelitian, lalu aplikasi notifikasi, lalu aplikasi notifikasi selesai dibuat dan dipasang"]'::JSONB, 0, '[C6] Kerangka bergerak dari masalah ke teori dan penelitian, ke produk, lalu ke hasil yang diambil dari tujuan. Menulis "aplikasi selesai dibuat" di kotak terakhir mengulang produk, bukan hasil yang diharapkan bagi pemustaka.', 18),
  (4, 'Dalam satu paragraf kajian teori, mahasiswa mengutip bunyi pasal peraturan perpustakaan tentang denda keterlambatan sepanjang 52 kata. Kutipan itu ditulis menyatu dalam kalimat dengan tanda petik, tanpa nomor halaman. Di paragraf yang sama ia juga mengutip langsung dua definisi pendek. Analisis yang paling tepat atas cara pengutipan itu adalah ...', '["Kutipan sudah benar karena bunyi pasal peraturan memang boleh dikutip langsung dengan memakai tanda petik", "Kutipan pasal sebaiknya diparafrase karena peraturan lebih lazim dirangkum dalam kajian pustaka", "Masalahnya terletak pada nomor halaman, sedangkan panjang dan jumlah kutipannya sudah sesuai pedoman", "Kutipan 52 kata seharusnya menjadi blok menjorok tanpa tanda petik, dan paragrafnya kelebihan kutipan langsung"]'::JSONB, 3, '[C4] Kutipan 40 kata atau lebih ditulis sebagai blok menjorok tanpa tanda petik, dan patokan kerjanya paling banyak satu kutipan langsung pendek per paragraf. Pasal peraturan memang boleh dikutip langsung, tetapi bentuk penulisannya tetap salah.', 19),
  (4, 'Dari matriks sintesis proyek aplikasi buku audio untuk perpustakaan sekolah luar biasa (rekaan), mahasiswa mencatat tiga kemungkinan celah. (1) Belum ada penelitian aplikasi buku audio bagi siswa tunanetra di kotanya. (2) Penelitian sejenis hanya menguji fungsi aplikasi dan belum menguji kegunaannya bersama siswa. (3) Belum ada peneliti yang memakai warna hijau pada antarmuka. Celah yang paling layak dijadikan justifikasi proyek adalah ...', '["Celah 3, karena hal yang belum pernah dilakukan peneliti lain dapat diajukan sebagai kebaruan proyek", "Celah 1 dan 2, karena keduanya celah pengguna dan cara menguji yang bermakna bagi masalah siswa", "Celah 1, karena cara menguji produk lebih tepat dibahas di bab metode daripada sebagai celah", "Ketiga celah setara, karena setiap perbedaan dengan penelitian lain sah dipakai sebagai celah"]'::JSONB, 1, '[C5] Celah populasi dan celah metode termasuk jenis celah yang disebut Chigbu dkk. (2023) dan berkaitan langsung dengan masalah pengguna. Warna antarmuka memang belum diteliti, tetapi tidak memecahkan masalah apa pun sehingga tidak membenarkan proyek.', 20),
  (5, 'Tim mahasiswa akan membuat sistem donasi buku berbasis web untuk perpustakaan umum kabupaten (rekaan). Daftar fitur sudah disepakati tertulis dengan kepala perpustakaan pada minggu pertama dan kecil kemungkinan berubah. Kepala perpustakaan hanya dapat ditemui sebulan sekali, dan ketiga anggota tim belum pernah membangun sistem. Model pengembangan mana yang paling sesuai dengan ciri proyek ini?', '["XP, karena perangkat lunak paling baik dikembangkan dalam putaran pendek yang melibatkan pengguna setiap minggu", "Waterfall, karena kebutuhan sudah disepakati sejak awal dan tahapnya yang berurutan mudah diikuti tim pemula", "RAD, karena purwarupa dapat diperbaiki berkali-kali bersama pengguna sehingga sistem cepat selesai", "GDLC, karena uji beta oleh pihak di luar tim menjamin mutu sistem sebelum dirilis ke pemustaka"]'::JSONB, 1, '[C4] Waterfall mengandaikan kebutuhan jelas sejak awal, dan tahap yang berurutan cocok untuk tim pemula. XP dan RAD menuntut pengguna yang sering ditemui, padahal mitra hanya ada sebulan sekali.', 1),
  (5, 'Draf proposal sebuah tim memuat kalimat: "Kami memakai ADDIE untuk aplikasi pemesanan ruang diskusi perpustakaan kampus karena Spatioti dkk. (2022) membuktikan bahwa ADDIE efektif di semua lingkungan pendidikan daring." Apa kelemahan utama alasan tersebut?', '["Meta-analisis lebih lemah daripada satu penelitian pengembangan, sehingga tim seharusnya mengutip satu penelitian saja", "ADDIE kurang cocok untuk produk aplikasi karena model itu lebih banyak dipakai untuk merancang bahan ajar cetak", "Sumber tahun 2022 sudah agak lama, sehingga sebaiknya diganti dengan Waruwu (2024) yang terbit lebih baru", "Bukti itu berasal dari pembelajaran daring, bukan layanan ruang diskusi, dan alasannya tidak menyebut ciri proyek tim"]'::JSONB, 3, '[C4] Bukti perlu berasal dari produk dan pengguna yang mirip, dan alasan memilih model harus dikaitkan dengan ciri proyek. Meta-analisis justru lebih kuat daripada satu penelitian, jadi pengecoh itu membalik urutan kekuatan bukti.', 2),
  (5, 'Rencana uji coba aplikasi katalog perpustakaan sekolah ditulis begini: "Sesudah telaah dua ahli, aplikasi langsung diuji di lapangan oleh 60 siswa yang mengisi angket kepuasan." Bila dibandingkan dengan urutan evaluasi formatif menurut Tessmer (1993), apa akibat paling mungkin dari rencana itu?', '["Uji perorangan dan kelompok kecil terlewati, sehingga titik tempat siswa macet baru diketahui saat sudah melibatkan banyak orang", "Tim kekurangan jumlah ahli, sehingga hasil telaah ahli tidak sah walaupun uji lapangannya sudah melibatkan 60 siswa", "Tim terlalu banyak melibatkan siswa, sehingga angket kepuasan tidak dapat diolah dan harus diganti dengan wawancara", "Urutan tim terbalik, karena uji lapangan sebaiknya dilakukan sebelum telaah ahli agar ahli dapat membaca hasil angket"]'::JSONB, 0, '[C4] Tessmer menata telaah ahli, uji perorangan, uji kelompok kecil, lalu uji lapangan. Melompati dua tahap tengah membuat masalah pemakaian baru terlihat di uji besar; jumlah ahli tidak dipersoalkan dalam urutan ini.', 3),
  (5, 'Sepuluh pemustaka mencoba aplikasi reservasi ruang diskusi lalu mengisi SUS (skala 1-5). Rata-rata jawaban per butir: B1 4,0; B2 2,0; B3 4,2; B4 4,4; B5 3,9; B6 1,8; B7 4,1; B8 2,1; B9 3,8; B10 2,2. Butir 4 bermakna "Saya merasa perlu bantuan orang teknis untuk dapat memakai aplikasi ini." Skor SUS produk 68,75. Butir mana yang paling menurunkan skor, dan tindak lanjut apa yang paling tepat?', '["Butir 6, karena rata-rata jawabannya paling rendah; layar yang dinilai paling rumit oleh pemustaka sebaiknya diberi petunjuk tambahan", "Butir 4, karena nilainya paling menyimpang dari butir lain; butir itu sebaiknya dikeluarkan dari angket agar skor mendekati patokan", "Butir 4, karena butir negatif itu banyak disetujui sehingga sumbangannya 0,6; langkah yang butuh bantuan dicari di catatan uji perorangan lalu direvisi", "Butir 9, karena rata-rata jawabannya terendah di antara butir positif; tim sebaiknya menambah fitur baru agar pemustaka lebih yakin"]'::JSONB, 2, '[C4] Butir genap bernada negatif dihitung 5 dikurangi jawaban, sehingga butir 4 menyumbang 5 - 4,4 = 0,6, jauh di bawah butir lain yang sekitar 3. Butir 6 justru baik karena jawaban rendah pada butir negatif menyumbang 3,2, dan mengeluarkan butir membuat skor tidak dapat dibandingkan.', 4),
  (5, 'Tim mengembangkan panduan digital unggah mandiri karya akhir ke repositori kampus. Validator yang dipilih adalah seorang dosen desain antarmuka dan seorang pengembang web. Keduanya diminta menilai dua aspek: kebenaran langkah unggah sesuai aturan repositori, serta tampilan dan navigasi. Apa masalah utama rancangan validasi ini?', '["Validatornya baru dua, padahal literatur umumnya menyarankan tujuh ahli atau lebih untuk produk seperti ini", "Pengembang web kurang tepat menjadi validator karena ia berasal dari bidang yang sama dengan tim pengembang", "Kebenaran langkah unggah dinilai ahli tampilan, bukan orang yang menguasai prosedur repositori", "Kedua validator menilai aspek yang sama, padahal sebaiknya tiap validator memakai instrumen yang berbeda"]'::JSONB, 2, '[C4] Kebenaran isi perlu dinilai ahli materi, misalnya pengelola repositori, karena ahli tampilan belum tentu tahu aturan unggah. Literatur belum sepakat tentang jumlah ideal ahli, jadi saran tujuh ahli bukan ketentuan baku.', 5),
  (5, 'Flowchart perpanjangan pinjaman yang dibuat tim berbunyi: Mulai, lalu Masuk akun, lalu Pilih buku yang sedang dipinjam, lalu keputusan "Ada pemesan lain?". Cabang "Tidak" menuju Perpanjang pinjaman lalu Selesai. Cabang "Ya" tidak diberi panah ke mana pun. Apa perbaikan paling penting sebelum flowchart ini diubah menjadi prototipe?', '["Memberi cabang \"Ya\" jalan keluar, misalnya pesan tanggal buku harus kembali, agar pemustaka tidak terhenti", "Mengganti belah ketupat keputusan dengan persegi panjang karena keputusan sebenarnya dijalankan oleh sistem", "Menambahkan layar petugas sirkulasi ke dalam flowchart agar prototipe juga memuat fungsi pengelolaan pinjaman", "Mengurangi panah karena urutan langkah sudah cukup terbaca dari letak simbol dari atas ke bawah"]'::JSONB, 0, '[C4] Setiap jawaban pada keputusan perlu jalan keluar sendiri supaya pengguna tidak terhenti. Mengganti simbol keputusan menjadi persegi panjang justru menyalahi simbol yang lazim.', 6),
  (5, 'Pada flowchart layanan peminjaman, langkah "Cari judul buku" diikuti keputusan "Judul ditemukan?". Tim akan membuat prototipe tiga layar di Figma. Bagaimana keputusan itu paling tepat diwujudkan dalam prototipe?', '["Sebagai dua layar terpisah yang sama-sama menampilkan tombol Pinjam, satu untuk buku tersedia dan satu untuk buku kosong", "Sebagai tombol \"Ya\" dan \"Tidak\" yang harus ditekan sendiri oleh pemustaka sesudah ia selesai mengetik judul buku di kotak pencarian", "Tidak perlu diwujudkan, karena keputusan itu terjadi di dalam sistem dan biasanya tidak terlihat oleh pemustaka", "Sebagai dua keadaan pada Layar Pencarian: daftar hasil bila judul ada, dan pesan serta saran kata kunci bila kosong"]'::JSONB, 3, '[C4] Belah ketupat diterjemahkan menjadi dua keadaan pada layar yang sama. Membiarkannya tak tergambar membuat validator tidak dapat menilai apa yang dilihat pemustaka saat pencarian gagal.', 7),
  (5, 'Untuk memilih ADDIE bagi e-modul literasi informasi, mahasiswa mengumpulkan dua bukti: (1) satu penelitian e-modul kimia SMK dengan skor validasi 92% dan nilai siswa naik dari 60 ke 85; (2) meta-analisis 23 artikel tentang ADDIE di pendidikan jarak jauh. Pernyataan mana yang paling tepat tentang kedua bukti itu?', '["Bukti pertama lebih kuat karena memuat angka validasi dan nilai tes, sedangkan meta-analisis lebih banyak merangkum pendapat", "Bukti kedua menggabungkan banyak penelitian, sedangkan bukti pertama hanya menunjukkan ADDIE berhasil di satu tempat", "Bukti pertama membuktikan bahwa ADDIE adalah penyebab naiknya nilai, sehingga bukti kedua tidak lagi diperlukan", "Kedua bukti sama kuatnya karena sama-sama memakai ADDIE, sehingga cukup dipilih salah satu saja untuk proposal"]'::JSONB, 1, '[C4] Meta-analisis menggabungkan hasil puluhan artikel, sedangkan satu penelitian hanya menunjukkan keberhasilan di satu tempat dan belum tentu karena modelnya. Angka yang tinggi tidak dengan sendirinya membuktikan sebab.', 8),
  (5, 'Laporan uji coba aplikasi layanan referensi daring menulis: "Rata-rata skor SUS dari 8 pemustaka adalah 72. Artinya 72% pemustaka puas. Karena di atas patokan 68, aplikasi tidak perlu direvisi lagi." Penilaian mana yang paling tepat atas laporan itu?', '["Skor 72 lazim tetapi bukan persentase kepuasan, dan tidak menunjukkan langkah yang menyulitkan pemustaka", "Laporan itu tepat seluruhnya, karena skor di atas 68 berarti produk sudah layak dan bebas dari masalah pemakaian", "Laporan itu keliru karena skor 72 berada di bawah rata-rata produk pendidikan sehingga aplikasi harus dirombak", "Laporan itu keliru terutama karena delapan pemustaka terlalu sedikit, sehingga skor SUS perlu diganti wawancara"]'::JSONB, 0, '[C5] Skor SUS bukan persentase, dan skor di sekitar 70 lazim untuk produk pendidikan. Skor di atas patokan belum menunjukkan langkah mana yang menyulitkan, jadi revisi tetap dibaca dari catatan uji perorangan.', 9),
  (5, 'Dua tim mengembangkan direktori koleksi lokal untuk perpustakaan daerah dalam satu semester. Tim Merah memakai sepuluh langkah penuh Borg dan Gall dengan tiga kali uji lapangan. Tim Biru menyederhanakannya menjadi tujuh langkah yang berakhir pada revisi akhir dan menuliskan langkah yang dilewati beserta alasannya. Penilaian mana yang paling dapat dipertanggungjawabkan?', '["Tim Merah lebih baik karena langkah yang lengkap umumnya menghasilkan produk yang lebih sahih, jadi sebaiknya tidak dikurangi", "Kedua tim kurang tepat karena model Borg dan Gall lebih cocok untuk permainan edukasi daripada direktori koleksi", "Tim Biru lebih realistis karena sepuluh langkah sulit selesai dalam satu semester, dan alasannya ditulis terbuka", "Tim Biru keliru karena penyederhanaan Borg dan Gall baru sah bila tahap uji lapangan ikut dihapus"]'::JSONB, 2, '[C5] Sepuluh langkah penuh sering terlalu panjang untuk satu semester, dan penyederhanaan sah bila langkah yang dilewati ditulis beserta alasannya. Kelengkapan memang keunggulan Borg dan Gall, tetapi tidak berguna bila tidak selesai.', 10),
  (5, 'Pada putaran pertama validasi panduan layanan sirkulasi, ahli media meminta gambar alur diperbesar, sedangkan ahli materi meminta teks penjelasan ditambah pada halaman yang sama. Halaman itu tidak cukup untuk keduanya. Tindakan mana yang paling tepat?', '["Mengikuti kedua saran sekaligus dengan memperkecil huruf, karena saran validator lebih aman diikuti daripada ditolak", "Memutuskan bersama dosen pembimbing, lalu mencatat keputusan dan alasannya di tabel jejak revisi", "Mengikuti saran dari validator yang memberi skor paling rendah agar skornya naik pada putaran berikutnya", "Mengabaikan kedua saran karena saling bertentangan, lalu meminta validator lain menilai ulang"]'::JSONB, 1, '[C5] Tidak semua saran harus diikuti; keputusan diambil bersama pembimbing dan dicatat di tabel jejak revisi. Memperkecil huruf demi menampung semua saran justru menurunkan keterbacaan yang dinilai ahli media.', 11),
  (5, 'Tim akan menguji kepraktisan aplikasi peminjaman buku perpustakaan kampus. Ada empat rencana peserta. Rencana mana yang paling dapat dipertahankan di depan pembimbing?', '["Lima anggota tim sendiri, karena mereka paling paham alur aplikasi sehingga uji coba berjalan cepat dan tanpa hambatan", "Dosen pembimbing sebagai pengguna utama, karena ia paling kritis dan paling memahami kriteria validasi", "Seratus pemustaka yang mengisi angket daring, karena jumlah peserta yang besar membuat hasilnya lebih sahih", "Satu petugas sirkulasi dan beberapa pemustaka yang belum pernah melihat aplikasi, dengan catatan titik macet"]'::JSONB, 3, '[C5] Peserta harus mewakili pengguna sebenarnya dan belum hafal alurnya, dan catatan tugas, waktu, serta titik berhenti lebih berguna untuk revisi. Angket massal tanpa uji kecil tidak menunjukkan di mana pengguna kesulitan.', 12),
  (5, 'Tim membangun katalog daring perpustakaan sekolah (rekaan). Fitur katalog akan ditambah sedikit demi sedikit sesuai permintaan pustakawan, pustakawan bersedia ditemui setiap minggu, dan anggota tim sudah terbiasa menulis kode bersama. Di proposal tim menulis: "Kami memilih XP karena agile adalah metode paling baru dan paling unggul." Penilaian mana yang paling tepat?', '["Pilihan dan alasannya kurang tepat, karena minat terhadap XP menurun sejak 2004 sehingga sebaiknya dihindari", "Pilihan dan alasannya sudah tepat, karena metode yang lebih baru biasanya membawa perbaikan atas metode lama", "Pilihan salah, karena produk untuk perpustakaan sekolah termasuk bahan ajar sehingga harus memakai model 4D", "XP dapat dipertahankan, tetapi alasannya diganti ciri proyek: kebutuhan berkembang dan mitra hadir tiap putaran"]'::JSONB, 3, '[C5] Ciri proyek ini cocok dengan XP, tetapi tidak ada metode yang paling cocok untuk semua proyek, jadi "paling baru" bukan alasan. Praktik XP juga masih banyak dipakai walau minat terhadap metodenya menurun.', 13),
  (5, 'Panduan pemanfaatan e-journal untuk mahasiswa baru dinilai dua validator. Ahli materi menilai kebenaran isi dan memberi rata-rata 3,8 dari 4. Ahli media menilai tampilan dan navigasi dan memberi rata-rata 2,6 dari 4. Tim menulis: "Skor validasi 3,2, produk layak." Penilaian mana yang paling tepat?', '["Kesimpulan tim tepat, karena rata-rata kedua validator sudah berada di atas titik tengah skala sehingga produk layak", "Kedua skor tidak dapat dirata-ratakan karena aspeknya berbeda; tampilan perlu direvisi walaupun isi sudah baik", "Tim harus menambah satu validator lagi agar rata-rata tiga orang dapat dihitung dan kesimpulan menjadi sah", "Skor ahli media perlu dibuang karena terlalu jauh dari skor ahli materi, sehingga skor validasi menjadi 3,8"]'::JSONB, 1, '[C5] Skor dua orang yang menilai aspek berbeda tidak dapat dirata-ratakan, sehingga hasilnya dilaporkan per aspek. Menambah validator tidak menyelesaikan masalah bila aspek yang dinilai tetap berbeda.', 14),
  (5, 'Mahasiswa menulis di proposal: "Sistem informasi peminjaman ruang baca kami pasti memperoleh skor SUS 84,5 karena Hasibuan dkk. (2026) juga memakai Waterfall dan memperoleh skor itu." Penilaian mana yang paling tepat atas kalimat tersebut?', '["Kalimat itu tepat, karena model yang sama akan menghasilkan skor kegunaan yang sama pada produk sejenis", "Kalimat itu keliru, karena skor SUS lebih lazim dipakai untuk produk yang dikembangkan dengan model RAD", "Angka itu layak dipakai sebagai pembanding, bukan jaminan, karena produk dan pengguna mahasiswa berbeda", "Kalimat itu keliru, karena proposal sebaiknya mengutip meta-analisis, bukan hasil satu penelitian pengembangan"]'::JSONB, 2, '[C5] Angka penelitian lain membantu menetapkan target dan dipakai sebagai pembanding, tetapi produk mahasiswa belum tentu mencapai skor yang sama. Keberhasilan juga belum tentu disebabkan oleh modelnya.', 15),
  (5, 'Jadwal proposal sebuah tim menempatkan validasi ahli satu kali saja pada minggu ke-14 dari 16 minggu, tanpa menyebut batas kelayakan. Harefa dan Laoli (2022) melaporkan skor ahli materi 58,6%, 75%, lalu 97% dalam tiga putaran revisi. Penilaian mana yang paling tepat?', '["Jadwal itu berisiko; tim perlu sedikitnya dua putaran penilaian dan batas kelayakan yang ditetapkan sejak awal", "Jadwal itu aman, karena validator jarang memberi skor rendah kepada produk yang dibuat mahasiswa tingkat akhir", "Jadwal itu keliru, karena tiga putaran revisi seperti pada Harefa dan Laoli perlu diikuti agar skor mencapai 97%", "Jadwal itu tidak perlu validasi ahli, karena skor SUS dari pengguna sudah cukup untuk menilai kelayakan produk"]'::JSONB, 0, '[C5] Skor validasi jarang langsung tinggi, jadi jadwal perlu ruang untuk sedikitnya dua putaran dan batas kelayakan ditetapkan sebelum validasi. Tiga putaran adalah temuan satu penelitian, bukan kewajiban.', 16),
  (5, 'Mahasiswa memakai model 4D untuk modul panduan layanan referensi digital bagi pemustaka baru, dengan waktu 16 minggu. Rancangan tahap mana yang paling tepat untuk ditulis di proposal?', '["Define: menulis isi modul (minggu 1-4); Design: memilih warna dan huruf (minggu 5-6); Develop: mencetak modul (minggu 7-10); Disseminate: menilai mutu modul bersama ahli (minggu 11-16)", "Define: wawancara petugas dan amati layanan (minggu 1-2); Design: prototipe dua halaman contoh (minggu 3-5); Develop: validasi ahli dua putaran dan uji coba kecil (minggu 6-13); Disseminate: serah terima ke mitra (minggu 14-16)", "Define: membuat prototipe di Figma (minggu 1-3); Design: uji lapangan dengan 60 pemustaka (minggu 4-8); Develop: wawancara petugas layanan (minggu 9-12); Disseminate: menyusun daftar kebutuhan (minggu 13-16)", "Define: wawancara petugas (minggu 1); Design: menulis isi modul (minggu 2-8); Develop: langsung menyebarkan modul ke pemustaka (minggu 9-12); Disseminate: validasi ahli satu kali (minggu 13-16)"]'::JSONB, 1, '[C6] Tahap Define menggali kebutuhan, Design membuat prototipe, Develop memuat validasi ahli dan uji coba terbatas, dan Disseminate menyerahkan produk. Menaruh penilaian ahli di Disseminate menyalahi celah 4D yang harus ditutup di tahap Develop.', 17),
  (5, 'Tim mengembangkan permainan edukasi pengenalan nomor klasifikasi koleksi untuk siswa SD di perpustakaan sekolah (rekaan) dengan model GDLC. Skema validasi mana yang paling tepat dirancang tim?', '["Pustakawan sekolah menilai kebenaran nomor klasifikasi, dosen multimedia menilai tampilan dan kendali, dan siswa di luar tim menjalankan uji beta", "Dosen multimedia menilai isi dan tampilan sendirian, lalu anggota tim memainkan permainan berulang kali untuk memastikan tidak ada galat sebelum dirilis", "Siswa SD menilai kebenaran nomor klasifikasi dengan angket, lalu pustakawan sekolah mencoba permainan sebagai penguji beta tanpa catatan tertulis", "Uji beta dilewati karena tahapan GDLC sudah menjamin mutu, sehingga cukup satu ahli materi menilai isi permainan sebelum rilis"]'::JSONB, 0, '[C6] Isi dinilai ahli materi, tampilan dan kendali dinilai ahli media, dan uji beta dikerjakan pihak di luar tim. GDLC sendiri belum menjamin proses yang bermutu, jadi melewati uji beta tidak dapat dibenarkan.', 18),
  (5, 'Proyek tim: sistem informasi peminjaman ruang diskusi di perpustakaan kampus. Fitur sudah disepakati dengan kepala layanan, waktunya satu semester, dan tim belum pernah membangun sistem. Paragraf alasan pemilihan model mana yang paling tepat untuk proposal?', '["Kami memilih RAD karena model ini paling cepat. Situs web Delima dkk. (2017) selesai dalam 30 minggu, sehingga sistem ruang diskusi kami juga kemungkinan besar selesai lebih cepat dari jadwal semester.", "Kami memilih ADDIE karena model ini paling terkenal dan paling banyak dipakai. Banyak penelitian sudah memakainya, sehingga tidak perlu alasan lain.", "Kami memilih XP karena metode agile adalah yang terbaru. Kebutuhan sistem kami akan kami gali sambil berjalan bersama kepala layanan setiap hari.", "Kami memilih Waterfall karena kebutuhan sudah disepakati dan tahapnya jelas bagi tim pemula. Hasibuan dkk. (2026) memakainya untuk sistem sekolah; skor SUS mereka menjadi pembanding."]'::JSONB, 3, '[C6] Alasan yang baik mengaitkan model dengan ciri proyek lalu menambahkan penelitian serupa sebagai pembanding. Paragraf RAD keliru karena mengubah hasil satu penelitian menjadi jaminan.', 19),
  (5, 'Tim mengembangkan fitur unggah mandiri karya akhir di repositori kampus. Rancangan uji coba mana yang paling tepat ditulis di subbab 3.3 proposal?', '["Lima anggota tim mengunggah berkas sambil dipandu pembuatnya langkah demi langkah, lalu angket SUS diisi sesudah diskusi panjang tentang kelebihan fitur unggah", "Satu dosen mencoba menu-menu utama tanpa tugas khusus, lalu hasilnya ditulis sebagai kesan umum bahwa fitur unggah \"mudah dipakai\"", "Tiga mahasiswa yang belum pernah mengunggah, lalu enam sampai sembilan peserta, mengerjakan tugas unggah sambil berpikir keras; SUS diisi sebelum diskusi", "Enam puluh mahasiswa langsung mengisi angket SUS yang butirnya disingkat menjadi lima agar cepat, tanpa mengerjakan tugas unggah tertentu"]'::JSONB, 2, '[C6] Rancangan yang baik memakai peserta yang mewakili pengguna, tugas yang mewakili fungsi utama, think aloud tanpa dibantu, dan SUS diisi sebelum diskusi. Menyingkat butir SUS membuat skor tidak dapat dibandingkan.', 20),
  (6, 'Seorang mahasiswa merancang angket kepuasan untuk aplikasi katalog daring perpustakaan sekolah. Spesifikasi produk di subbab 1.5 proposalnya memuat empat ciri: pencarian judul, tampilan di ponsel, informasi ketersediaan buku, dan fitur pemesanan. Ia langsung menulis 10 butir tanpa kisi-kisi. Hasilnya 5 butir tentang tampilan, 3 butir tentang pencarian, 2 butir tentang ketersediaan, dan tidak ada butir tentang pemesanan. Apa penyebab utama ketimpangan ini dan perbaikan yang paling tepat?', '["Jumlah butir terlalu sedikit, sehingga angket perlu ditambah menjadi 20 butir agar ciri produk yang lain ikut tertanya.", "Skala jawaban belum seragam, sehingga tiap butir perlu diberi keterangan skor 1 sampai 5 yang sama di atas angket.", "Ciri produk belum dipetakan menjadi aspek dan indikator, sehingga kisi-kisi disusun dulu lalu butir ditulis ulang.", "Validator belum dilibatkan, sehingga angket perlu langsung dinilai ahli agar butir tampilan yang berlebih dihapus."]'::JSONB, 2, '[C4] Bab ini menempatkan kisi-kisi (aspek, indikator, lalu butir) sebelum butir ditulis; tanpa itu butir menumpuk pada hal yang mudah ditanyakan dan ciri pemesanan terlewat. Menambah butir tanpa kisi-kisi belum menjamin ciri pemesanan terwakili.', 1),
  (6, 'Lembar observasi di ruang baca digital sebuah perpustakaan kampus diisi dua pengamat pada hari yang sama, dan hasil keduanya hampir selalu sama. Namun, butir-butirnya mencatat jumlah pengunjung yang masuk, padahal tujuan proyek adalah menilai apakah pemustaka mampu memakai mesin pencari katalog tanpa bantuan petugas. Bagaimana kualitas instrumen ini paling tepat dianalisis?', '["Instrumen reliabel karena hasil kedua pengamat konsisten, tetapi belum valid karena butirnya tidak mengukur kemampuan yang dituju.", "Instrumen valid sekaligus reliabel, karena kesepakatan dua pengamat yang tinggi sudah membuktikan bahwa butirnya mengukur dengan tepat.", "Instrumen valid tetapi belum reliabel, karena dua pengamat terlalu sedikit untuk memastikan hasil observasi tetap konsisten.", "Instrumen belum valid dan belum reliabel, karena lembar observasi tidak dapat dipakai untuk menilai kemampuan memakai katalog."]'::JSONB, 0, '[C4] Reliabilitas menyangkut konsistensi, sedangkan validitas menyangkut ketepatan sasaran ukur; bab ini menegaskan instrumen yang reliabel belum tentu valid. Pengecoh terkuat menyamakan hasil yang konsisten dengan hasil yang tepat.', 2),
  (6, 'Tiga ahli menilai relevansi empat butir lembar validasi aplikasi repositori kampus dengan skala 1 sampai 4. Skor butir 1: 4, 4, 3. Butir 2: 4, 2, 4. Butir 3: 3, 3, 3. Butir 4: 2, 2, 4. Patokannya I-CVI di atas 0,80. Seorang mahasiswa mengusulkan: butir 3 direvisi karena rata-rata skornya rendah, butir 2 dipertahankan karena dua ahli memberi skor 4, dan butir 4 dibuang. Keputusan tindak lanjut mana yang paling tepat?', '["Usulan diterima, karena rata-rata skor butir 3 memang rendah dan butir 2 sudah disetujui dua dari tiga ahli.", "Butir 4 dibuang, butir 2 dan 3 direvisi, karena keduanya mendapat skor di bawah 4 dari sedikitnya satu ahli.", "Keempat butir dinilai ulang oleh ahli lain, karena penilaian ketiga ahli berbeda cukup jauh pada butir 2 dan 4.", "Butir 1 dan 3 dipertahankan; butir 2 dan 4 direvisi menurut catatan ahli yang memberi skor 2, lalu dinilai ulang."]'::JSONB, 3, '[C5] I-CVI butir 1 dan 3 adalah 1,00, butir 2 adalah 0,67, dan butir 4 adalah 0,33, sehingga butir 2 dan 4 berada di bawah ambang; bab ini merevisi butir seperti itu menurut catatan ahli lalu menilainya ulang. Rata-rata skor tidak dipakai, sehingga butir 3 yang berskor 3 dari ketiga ahli tetap relevan.', 3),
  (6, 'Tiga validator menilai lembar validasi delapan butir (skala 1 sampai 5) untuk aplikasi peminjaman e-book perpustakaan umum. Tiap aspek terdiri atas dua butir sehingga skor maksimumnya 30. Jumlah skor per aspek: isi 27, tampilan 26, kemudahan penggunaan 19, dan kesesuaian dengan tujuan 28. Persentase seluruh lembar adalah 100 ÷ 120 × 100% = 83%. Kesimpulan mana yang paling tepat untuk menentukan revisi?', '["Keempat aspek cukup baik karena persentase seluruh lembar 83%, sehingga produk dapat diuji coba tanpa revisi lebih dulu.", "Aspek kemudahan penggunaan direvisi lebih dulu karena persentasenya sekitar 63%, jauh di bawah persentase seluruh lembar.", "Aspek tampilan direvisi lebih dulu karena tampilan paling cepat dikeluhkan pengguna, walaupun persentasenya sekitar 87%.", "Keempat aspek direvisi sama banyak karena persentase seluruh lembar belum mencapai 90% pada skala lima pilihan."]'::JSONB, 1, '[C4] Bab ini menganjurkan persentase per aspek supaya bagian yang perlu direvisi terlihat; 19 ÷ 30 × 100% kira-kira 63%, terendah dan jauh di bawah 83%. Persentase seluruh lembar menyembunyikan aspek yang lemah.', 4),
  (6, 'Mahasiswa mewawancarai delapan pemustaka tentang fitur pengingat jatuh tempo pada aplikasi perpustakaan sekolah. Kutipan yang sudah dikode antara lain: "pengingatnya membantu saya tidak kena denda", "notifikasinya terlalu sering, jadi saya matikan", "enak karena dikirim tiga hari sebelumnya", dan "bunyinya mengganggu saat pelajaran". Bagaimana kode-kode ini paling tepat dikelompokkan?', '["Dipisah menjadi dua tema umum, yaitu \"manfaat aplikasi\" dan \"gangguan aplikasi\", tanpa menyebut fitur pengingat.", "Satu tema \"pengingat jatuh tempo\" dengan dua subtema, yaitu pengingat sebagai kelebihan dan sebagai kekurangan.", "Dihitung jumlah kutipan positif dan negatif, lalu dilaporkan sebagai persentase tanpa perlu menyusun tema.", "Kutipan negatif disisihkan karena kemungkinan besar berasal dari pemustaka yang belum terbiasa memakai aplikasi."]'::JSONB, 1, '[C4] Bab ini memakai subtema ketika sebagian responden menilai hal yang sama sebagai kelebihan dan sebagian lain sebagai kekurangan. Memisah menjadi dua tema umum memutus kaitan kedua penilaian dengan fitur yang sama.', 5),
  (6, 'Empat butir angket aplikasi buku tamu digital perpustakaan desa (skala 1 sampai 5) berbunyi: (i) "Formulir buku tamu mudah diisi." (ii) "Tampilan aplikasi menarik dan proses penyimpanan data cepat." (iii) "Petunjuk pengisian mudah dipahami." (iv) "Tombol kirim terlihat jelas di layar ponsel." Butir mana yang paling bermasalah dan apa alasannya?', '["Butir (i), karena kata \"mudah\" bersifat subjektif sehingga tidak dapat dijawab dengan skala Likert lima pilihan.", "Butir (iv), karena menyebut perangkat tertentu sehingga pemustaka pengguna komputer tidak dapat menjawabnya.", "Butir (iii), karena petunjuk pengisian termasuk aspek isi sehingga sebaiknya dipisah dari aspek kemudahan penggunaan.", "Butir (ii), karena memuat dua hal sekaligus sehingga skor tidak menunjukkan hal mana yang dinilai responden."]'::JSONB, 3, '[C4] Bab ini meminta butir yang memuat dua hal, seperti tampilan dan kecepatan, dipecah menjadi dua butir. Kata "mudah" pada butir (i) lazim dinilai dengan skala Likert sehingga bukan masalah utama.', 6),
  (6, 'Rencana pengumpulan data proyek layanan referensi daring di perpustakaan kampus memuat tiga data: (1) skor angket kepraktisan dari 25 mahasiswa, (2) transkrip wawancara dengan tiga pustakawan referensi, dan (3) komentar tertulis validator pada lembar validasi. Pasangan teknik analisis mana yang paling sesuai?', '["Data 1 dianalisis deskriptif dengan persentase; data 2 dan 3 dianalisis tematik dengan pengodean lalu pengelompokan tema.", "Data 1 dan 3 dianalisis deskriptif dengan rata-rata; data 2 dianalisis tematik karena wawancara menghasilkan jawaban terbuka.", "Ketiga data dianalisis deskriptif, karena komentar dan transkrip dapat dihitung frekuensi katanya lalu dibuat persentase.", "Data 1 dianalisis tematik dengan merangkum skor; data 2 dan 3 dianalisis deskriptif dengan grafik kutipan terbanyak."]'::JSONB, 0, '[C4] Bab ini menyebut transkrip wawancara, catatan observasi, dan komentar tertulis pada lembar validasi sebagai bahan analisis tematik, sedangkan skor angket diolah deskriptif. Pengecoh terkuat lupa bahwa komentar validator juga berupa data kata-kata.', 7),
  (6, 'Angket uji coba aplikasi jadwal piket untuk enam petugas layanan di sebuah perpustakaan sekolah meminta data diri berupa nama lengkap, jabatan, lama bekerja, dan jenis kelamin. Rencana analisisnya hanya menghitung persentase kepraktisan dari seluruh responden. Apa masalah utama bagian data diri tersebut?', '["Data diri terlalu sedikit, sehingga perlu ditambah usia dan pendidikan terakhir agar hasil analisis menjadi lebih rinci.", "Data diri seharusnya ditaruh di akhir angket, sebab responden lebih jujur bila menjawab butir inti lebih dulu.", "Data diri tidak dipakai dalam analisis, padahal pada enam petugas jabatan dan lama kerja dapat menunjuk satu orang.", "Data diri sebaiknya diganti kode responden, karena nama lengkap menyulitkan pengolahan skor di lembar kerja."]'::JSONB, 2, '[C4] Bab ini mengingatkan bahwa pertanyaan demografis dapat membuat responden merasa identitasnya terlacak, terutama di unit kecil, sehingga hanya data yang dipakai dalam analisis yang diminta. Letak data diri di awal atau akhir angket tidak menjawab masalah itu.', 8),
  (6, 'Laporan uji coba aplikasi pengusulan buku di perpustakaan kampus menulis: "Sembilan responden memberi skor total 288 dari skor maksimum 360, sehingga persentase kepraktisan 80%. Setelah melihat hasil, peneliti memilih kriteria yang menggolongkan 76-100% sebagai sangat praktis." Penilaian mana yang paling tepat atas laporan ini?', '["Laporan sudah tepat, karena perhitungannya benar dan kriteria apa pun sah selama rentangnya ditulis jelas di laporan.", "Laporan keliru hitung, karena persentase kepraktisan seharusnya dihitung dari rata-rata skor per responden, bukan jumlah skor.", "Laporan kurang tepat, karena dengan sembilan responden persentase kepraktisan perlu dihitung per butir, bukan per angket.", "Hitungannya benar, tetapi kriteria dipilih sesudah data terlihat; kriteria dan sumbernya seharusnya ditetapkan sebelumnya."]'::JSONB, 3, '[C5] Karena batas kategori berbeda antarpenelitian, bab ini meminta kriteria ditetapkan sebelum data dikumpulkan dan sumbernya ditulis di subbab 3.5 proposal. Perhitungan 288 ÷ 360 × 100% = 80% sendiri sudah benar.', 9),
  (6, 'Dua mahasiswa merencanakan bukti konsistensi lembar validasi aplikasi kurasi koleksi lokal perpustakaan daerah yang akan dinilai tiga ahli. Laras menulis: "Reliabilitas diuji dengan Cronbach''s Alpha dari skor tiga ahli." Tegar menulis: "Konsistensi dilihat dari tingkat kesepakatan antarpenilai, dan cara menghitungnya dijelaskan di bagian metode." Rencana mana yang lebih dapat dipertanggungjawabkan untuk proyek ini dan mengapa?', '["Rencana Laras, karena Tabel 6.5 mencantumkan Cronbach''s Alpha di atas 0,70 sebagai ukuran reliabilitas instrumen.", "Rencana Tegar, karena untuk dua sampai tiga validator kesepakatan antarpenilai yang dijelaskan terbuka sudah memadai.", "Rencana Laras, karena kesepakatan antarpenilai lebih tepat dipakai untuk menunjukkan validitas isi daripada konsistensi.", "Keduanya kurang tepat, karena lembar validasi ahli cukup diperiksa validitas isinya, sedangkan reliabilitas diuji pada angket."]'::JSONB, 1, '[C5] Bab ini menyatakan bahwa untuk validator terbatas (2-3 orang), kesepakatan antarpenilai yang dijelaskan transparan di bagian metode sudah memadai sebagai bukti awal konsistensi. Tabel 6.5 memuat Cronbach''s Alpha sebagai salah satu ukuran, bukan satu-satunya.', 10),
  (6, 'Untuk angket kepuasan pemustaka lanjut usia di perpustakaan umum kabupaten, tim mempertimbangkan tiga rancangan: (a) skala lima pilihan dengan keterangan 1 = sangat tidak sesuai sampai 5 = sangat sesuai di atas angket untuk semua butir; (b) skala tujuh pilihan karena menurut telaah memberi koefisien validitas dan reliabilitas terbaik; (c) skala empat pilihan agar tidak ada jawaban tengah. Tim tidak punya alasan khusus untuk membuat responden condong ke satu sisi. Rancangan mana yang paling layak dan mengapa?', '["Rancangan (a), karena lima pilihan lazim, lebih ringan bagi responden, dan keterangan seragam membuat skor dapat dibandingkan.", "Rancangan (b), karena koefisien validitas dan reliabilitas yang lebih tinggi lebih penting daripada beban pengisian bagi lansia.", "Rancangan (c), karena kecenderungan memilih jawaban tengah dapat mengganggu hasil, sehingga skala genap lebih aman di sini.", "Rancangan (b) atau (c) sama baiknya, karena jumlah pilihan tidak berpengaruh pada mutu data selama butirnya valid."]'::JSONB, 0, '[C5] Bab ini menilai lima pilihan sudah memadai dan lebih ringan bagi responden, dengan keterangan angka yang sama untuk semua butir; skala genap hanya cocok bila peneliti ingin responden condong ke satu sisi. Keunggulan koefisien skala tujuh tidak otomatis mengalahkan beban bagi responden lanjut usia.', 11),
  (6, 'Draf laporan proyek aplikasi peminjaman ruang diskusi perpustakaan kampus memuat ringkasan tahapan model pengembangan, tabel persentase validasi ahli, persentase kepraktisan dari uji coba, dan kutipan wawancara yang sudah dikelompokkan dalam tema. Bagian penutupnya hanya berbunyi "Produk layak digunakan." Menurut uraian bab tentang laporan yang sistematis, apa kekurangan terpenting draf ini?', '["Belum ada uji statistik inferensial, sehingga kesimpulan kelayakan produk belum dapat diberlakukan di perpustakaan lain.", "Kutipan wawancara terlalu banyak, karena laporan proyek vokasi cukup menyajikan angka persentase dari angket.", "Belum ada rekomendasi perbaikan produk yang diturunkan dari temuan analisis deskriptif dan tematik tersebut.", "Ringkasan tahapan model tidak diperlukan, karena proses pengembangan sudah dijelaskan di Bab 3 proposal."]'::JSONB, 2, '[C5] Bab ini menyebut laporan yang sistematis memuat ringkasan proses, hasil validasi dan uji coba, temuan analisis, serta rekomendasi perbaikan berdasarkan temuan itu. Uji statistik inferensial tidak dituntut dalam laporan proyek mata kuliah ini.', 12),
  (6, 'Demi mengejar jadwal, seorang mahasiswa berencana menyebarkan angket aplikasi pencarian skripsi di repositori kampus kepada 40 mahasiswa minggu ini, lalu meminta dua ahli menilai butir angket sesudah data terkumpul. Bila ada butir yang buruk, ia akan membuangnya saat analisis. Penilaian mana yang paling tepat atas rencana ini?', '["Rencana dapat diterima, karena butir yang buruk tetap dapat dikenali dan dibuang ketika data dianalisis secara statistik.", "Rencana dapat diterima asalkan jumlah responden dinaikkan, sebab sampel yang besar menutupi kelemahan isi butir.", "Rencana kurang tepat, karena validitas isi diperiksa ahli sebelum angket dipakai; cacat isi tidak dapat diperbaiki analisis.", "Rencana kurang tepat, karena penilaian ahli lebih diperlukan untuk pedoman wawancara daripada untuk angket berskala Likert."]'::JSONB, 2, '[C5] Bab ini menyatakan validitas isi diperiksa sejak perancangan butir karena instrumen yang cacat isinya tidak dapat diperbaiki dengan analisis sesudah data terkumpul, dan validasi ahli mendahului uji coba pengguna. Membuang butir saat analisis berarti data dari butir itu sudah terbuang percuma.', 13),
  (6, 'Tujuan uji coba sebuah proyek adalah memahami alasan pustakawan sekolah jarang memakai fitur laporan statistik pada aplikasi otomasi perpustakaan. Tiga rencana diajukan: (a) angket skala 1 sampai 5 tentang kepuasan umum untuk 30 pustakawan; (b) wawancara mendalam dengan lima pustakawan dan observasi saat mereka menyusun laporan; (c) menghitung jumlah klik fitur laporan selama sebulan. Rencana mana yang paling sesuai dengan tujuan dan mengapa?', '["Rencana (b), karena tujuan menanyakan alasan di balik perilaku, dan alasan lebih tergali lewat wawancara dan observasi.", "Rencana (a), karena 30 responden memberi hasil yang lebih dapat dipercaya daripada lima orang yang diwawancarai.", "Rencana (c), karena data klik bersifat objektif sehingga langsung menjelaskan mengapa fitur itu jarang dipakai.", "Rencana (a), karena persentase kepuasan umum dari 30 pustakawan sudah cukup untuk menyimpulkan alasan mereka menghindari fitur."]'::JSONB, 0, '[C5] Bab ini menyebut teknik kualitatif seperti wawancara mendalam dan observasi cocok untuk memahami alasan di balik penilaian pengguna. Jumlah responden yang lebih besar pada angket tidak menjawab pertanyaan "mengapa".', 14),
  (6, 'Kisi-kisi lembar validasi aplikasi peta rak buku perpustakaan kampus memuat empat aspek: isi, tampilan, kemudahan penggunaan, dan kecepatan server. Spesifikasi produk di subbab 1.5 proposal hanya menyebut tiga ciri: denah rak, petunjuk arah ke rak, dan tampilan yang ramah ponsel. Butir 9 berbunyi "Warna logo perpustakaan sesuai identitas lembaga", tetapi tidak tercantum di kisi-kisi. Penilaian mana yang paling tepat?', '["Kisi-kisi sudah baik karena empat aspek memenuhi jumlah minimal; butir 9 cukup ditambahkan sebagai butir pelengkap.", "Kisi-kisi perlu ditambah aspek identitas lembaga agar butir 9 punya baris asal, tanpa mengubah aspek lainnya.", "Kisi-kisi sudah baik, tetapi butir 9 sebaiknya dipindah ke pedoman wawancara karena berupa penilaian selera.", "Pemeriksaan dua arah gagal: aspek kecepatan server tidak bersumber dari spesifikasi, dan butir 9 tidak punya asal."]'::JSONB, 3, '[C5] Bab ini meminta pemeriksaan dua arah: setiap aspek dapat ditelusuri ke spesifikasi produk atau tujuan proyek, dan setiap butir punya baris asal di kisi-kisi. Menambah aspek identitas lembaga hanya memperbaiki satu arah dan tetap tidak bersumber dari spesifikasi.', 15),
  (6, 'Seorang mahasiswa melaporkan: "Butir 6 lembar validasi aplikasi buku audio di perpustakaan sekolah luar biasa mendapat I-CVI 0,67 dari tiga ahli. Nilai ini mendekati 0,78 sehingga butir dinyatakan layak dengan revisi kecil tanpa dinilai ulang." Penilaian mana yang paling tepat?', '["Pernyataan dapat diterima, karena selisih 0,67 dan 0,78 kecil dan dosen pengampu berwenang melonggarkan ambang.", "Pernyataan keliru, karena dengan tiga ahli butir baru lolos bila I-CVI 1,00; butir 6 direvisi lalu dinilai ulang.", "Pernyataan keliru, karena butir dengan I-CVI 0,67 sebaiknya dibuang daripada diperbaiki dengan catatan ahli.", "Pernyataan dapat diterima, karena ambang 0,78 dirancang untuk panel lima ahli atau lebih, sehingga longgar bagi tiga ahli."]'::JSONB, 1, '[C5] Dengan tiga ahli, nilai I-CVI hanya 0; 0,33; 0,67; atau 1,00, sehingga ambang 0,80 maupun 0,78 sama-sama menuntut 1,00, dan contoh di bab ini merevisi butir menurut catatan ahli lalu menilainya ulang. Kewenangan dosen menentukan standar tidak mengubah fakta bahwa satu dari tiga ahli menilai butir itu tidak relevan.', 16),
  (6, 'Spesifikasi produk sebuah proposal menyebut: "Aplikasi layanan pesan-antar buku antarfakultas menampilkan status pengantaran buku secara langsung." Mahasiswa diminta menyusun satu baris kisi-kisi angket pengguna yang memuat aspek, indikator, dan contoh butir dari ciri ini. Rancangan mana yang paling baik?', '["Aspek informasi pengantaran; indikator: pemustaka tahu status pesanan tanpa bertanya ke petugas; butir: \"Saya dapat mengetahui status pengantaran tanpa bertanya ke petugas.\"", "Aspek kepuasan; indikator: pemustaka merasa puas terhadap aplikasi secara keseluruhan; butir: \"Saya puas dengan aplikasi ini dan akan merekomendasikannya kepada teman-teman saya.\"", "Aspek informasi pengantaran; indikator: tampilan status pengantaran menarik bagi pemustaka; butir: \"Tampilan status pengantaran menarik dan informasinya akurat.\"", "Aspek teknologi; indikator: aplikasi memakai teknologi pelacakan pesanan secara langsung; butir: \"Apakah aplikasi ini memakai teknologi pelacakan secara waktu nyata?\""]'::JSONB, 0, '[C6] Rancangan terbaik menurunkan aspek dari ciri produk, indikator yang dapat diamati pengguna, dan butir yang memuat satu hal. Opsi tampilan status menarik memuat dua hal dalam satu butir dan indikatornya tidak sesuai dengan ciri yang dimaksud.', 17),
  (6, 'Seorang mahasiswa mengembangkan modul pelatihan literasi informasi untuk pustakawan sekolah. Pada AM-6 ia harus menyusun rencana singkat yang menjelaskan siapa respondennya, kapan data dikumpulkan, dan bagaimana data dianalisis. Rancangan rencana mana yang paling utuh?', '["Pustakawan mengisi angket kepraktisan sesudah modul selesai dibuat; skornya diubah menjadi persentase, lalu kategori kelayakan dipilih peneliti ketika laporannya sedang ditulis.", "Dua ahli menilai modul dan pustakawan diwawancarai pada pekan yang sama agar ringkas; skor dan jawaban wawancara dirata-rata menjadi satu angka.", "Lima pustakawan diwawancarai sebelum modul disusun; transkripnya dikode menjadi tema, lalu tema itu dipakai sebagai bukti bahwa modul layak.", "Ahli materi dan media menilai modul lebih dulu; sesudah revisi, pustakawan mencoba modul, mengisi angket, dan diwawancarai; skor dipersentasekan, wawancara dianalisis tematik."]'::JSONB, 3, '[C6] Rencana yang utuh mengikuti pola dua tahap di bab ini (validasi ahli lalu uji coba pengguna) dan memasangkan tiap jenis data dengan teknik analisisnya. Opsi angket saja menetapkan kriteria sesudah data terkumpul dan tidak memuat validasi ahli.', 18),
  (6, 'Sebuah butir angket untuk aplikasi pengingat pengembalian buku di perpustakaan umum berbunyi: "Notifikasi aplikasi tepat waktu dan bahasanya sopan." Pada uji keterbacaan, tiga pemustaka ragu memberi skor karena notifikasinya tepat waktu, tetapi bahasanya mereka rasa kaku. Perbaikan mana yang paling baik?', '["Butir diganti menjadi \"Notifikasi aplikasi secara umum baik\" agar pemustaka cukup memberi satu penilaian menyeluruh.", "Butir dipecah menjadi \"Notifikasi datang sebelum tanggal jatuh tempo\" dan \"Bahasa notifikasi terasa sopan\".", "Butir dipertahankan, lalu skala diganti menjadi tujuh pilihan agar pemustaka dapat memilih nilai di tengah keduanya.", "Butir dipertahankan, tetapi petunjuk angket ditambah \"jawablah menurut hal yang paling penting bagi responden\"."]'::JSONB, 1, '[C6] Butir yang memuat dua hal dipecah menjadi dua butir, masing-masing dengan rumusan yang dapat diamati pemustaka. Mengganti skala menjadi tujuh pilihan tidak menghilangkan kebingungan karena responden tetap menilai dua hal dengan satu angka.', 19),
  (6, 'Hasil uji coba aplikasi katalog suara untuk pemustaka tunanetra di perpustakaan daerah (data rekaan): persentase kepraktisan 84% dengan kriteria yang ditetapkan sebelum uji coba, tetapi aspek kemudahan navigasi hanya 65%. Analisis tematik wawancara menghasilkan tema "perintah suara sulit dikenali di ruang ramai", didukung kutipan empat dari enam responden. Rumusan rekomendasi laporan mana yang paling baik?', '["Produk dinyatakan sangat praktis dengan skor 84%, sehingga dapat langsung dipakai di seluruh layanan tanpa revisi lanjutan.", "Produk perlu dikembangkan ulang dari awal, karena empat responden mengeluh dan skor navigasi belum mencapai kriteria.", "Produk praktis secara umum; navigasi direvisi dengan tombol selain perintah suara, lalu diuji ulang di ruang yang ramai.", "Produk praktis secara umum; keluhan perintah suara dicatat sebagai saran karena berasal dari wawancara, bukan dari angket."]'::JSONB, 2, '[C6] Rekomendasi yang baik menggabungkan angka per aspek dan tema wawancara menjadi perbaikan yang spesifik, lalu meminta uji ulang. Mengembangkan ulang dari awal berlebihan karena persentase keseluruhan sudah memenuhi kriteria.', 20);
INSERT INTO quiz_questions (kind, module_id, course_id, question, options, answer_idx, explanation, order_num)
