-- migration_v42: bank soal Tes Formatif HOTS, 20 soal per bab untuk Bab 1-6 (antrean #235, 18 Okt 2026).
-- Permintaan Johan: soal HOTS per bab, live di web, soal dan urutannya berubah tiap pengerjaan.
-- Aplikasi mengambil 10 dari 20 soal secara acak tiap pengerjaan, lalu mengacak urutan soal dan urutan opsi.
-- Soal formatif lama untuk enam topik ini DIHAPUS lalu diganti (keputusan Johan). Nilai lama (quiz_attempts) tidak hilang.
-- Topik dicari lewat order_num 1-6 di mata kuliah "Metode Penelitian dan Pengembangan". Pembahasan diawali level Bloom, mis. "[C5] ...".
-- Jalankan sekali di Supabase SQL Editor. Seluruh berkas satu transaksi: kalau satu bagian gagal, tidak ada yang berubah.

-- LANGKAH 1 (pratinjau, boleh dijalankan sendiri dulu): harus 6 baris, order_num 1-6, judul sesuai Bab 1-6.
-- select m.order_num, m.id, m.title, (select count(*) from quiz_questions qq where qq.kind = 'formatif' and qq.module_id = m.id) as soal_formatif_lama
-- from modules m join courses c on c.id = m.course_id where c.name = 'Metode Penelitian dan Pengembangan' and m.order_num between 1 and 6 order by m.order_num;

BEGIN;

DO $$
DECLARE n INT; k INT;
BEGIN
  SELECT count(*) INTO k FROM courses WHERE name = 'Metode Penelitian dan Pengembangan';
  IF k <> 1 THEN RAISE EXCEPTION 'Mata kuliah "Metode Penelitian dan Pengembangan" ditemukan % kali (harus 1). Tidak ada yang diubah.', k; END IF;
  SELECT count(*) INTO n FROM modules m JOIN courses c ON c.id = m.course_id
   WHERE c.name = 'Metode Penelitian dan Pengembangan' AND m.order_num BETWEEN 1 AND 6;
  IF n <> 6 THEN RAISE EXCEPTION 'Topik order_num 1-6 ditemukan % (harus 6). Tidak ada yang diubah.', n; END IF;
END $$;

CREATE TEMP TABLE soal_baru (bab INT, question TEXT, options JSONB, answer_idx INT, explanation TEXT, order_num INT) ON COMMIT DROP;

DELETE FROM quiz_questions qq
 USING modules m, courses c
 WHERE qq.kind = 'formatif' AND qq.module_id = m.id AND c.id = m.course_id
   AND c.name = 'Metode Penelitian dan Pengembangan' AND m.order_num BETWEEN 1 AND 6;

SELECT 'formatif', m.id, m.course_id, s.question, s.options, s.answer_idx, s.explanation, s.order_num
  FROM soal_baru s
  JOIN modules m ON m.order_num = s.bab
  JOIN courses c ON c.id = m.course_id AND c.name = 'Metode Penelitian dan Pengembangan'
 ORDER BY s.bab, s.order_num;

COMMIT;

